{"command":"mkdir -p /tmp/difftest/src
cat > /tmp/difftest/Cargo.toml <<'EOF'
[package]
name="difftest"
version="0.1.0"
edition="2021"
[dependencies]
diff="0.1"
difflib="0.4"
EOF
cat > /tmp/difftest/src/main.rs <<'EOF'
fn main(){
    let cases=vec![
        ("hello world foo","hello brave world"),
        ("count 1","count 2"),
        ("aaa bbb","aaabbb"),
        ("a b c","c b a"),
        ("hello","hallo"),
        ("hello world","hello world!"),
        ("a  b","a b"),
        ("foo_bar baz","foo_baz baz"),
        ("a/b/c","a/x/c"),
        ("key=value other=1","key=val2 other=1"),
    ];
    for (a,b) in &cases {
        println!("WORDS {:?} -> {:?}",a,b);
        for r in diff::words(a,b){ println!("  {:?}",r); }
        println!("CHARS");
        // for r in diff::chars(a,b){ println!("  {:?}",r); }
    }
    let lc=vec![("a\nb\nc","c\nb\na"),("a\nb\nc","x\ny\nz"),("one\ntwo\nthree","one\nthree")];
    for (a,b) in &lc {
        println!("LINES {:?} -> {:?}",a,b);
        for r in diff::lines(a,b){ println!("  {:?}",r); }
    }
    // difflib
    println!("=== difflib sequencematcher words ===");
    for (a,b) in &cases {
        let aw:Vec<&str>=a.split(' ').collect();
        let bw:Vec<&str>=b.split(' ').collect();
        let sm=difflib::sequencematcher::SequenceMatcher::new(&aw,&bw);
        println!("{:?}->{:?} opcodes {:?}",a,b,sm.get_opcodes());
    }
}
EOF
cd /tmp/difftest && cargo run --offline -q 2>&1 | head -n 300
"}

