{"command":"python3 - << 'PY'
import subprocess, json,string
def second_record(a,b):
    open("/tmp/outs.json","w").write(json.dumps([a+"\n",b+"\n"]))
    open("/tmp/counter","w").write("0")
    script = "python3 -c \"import json; i=int(open('/tmp/counter').read()); open('/tmp/counter','w').write(str(i+1)); outs=json.load(open('/tmp/outs.json')); print(outs[min(i,len(outs)-1)], end='')\""
    try:
        p=subprocess.run(["./executable","-b","-n","0.25","-d","word",script],capture_output=True,timeout=1.0)
        out=p.stdout.decode()
    except subprocess.TimeoutExpired as e: out=(e.stdout or b'').decode()
    rec=out.split("=========================")[-1]
    return rec.strip().splitlines()
for pun in string.punctuation:
    a=f"aa{pun}bb cc"
    b=f"aa{pun}xx cc"
    lines=second_record(a,b)
    print(f"{pun!r}: {lines}")
PY
"}

