use unicode_segmentation::UnicodeSegmentation;
fn main(){
 let cases=vec![
        ("hello world foo","hello brave world"),
        ("count 1","count 2"),
        ("aaa bbb","aaabbb"),
        ("a b c","c b a"),
        ("hello","hallo"),
        ("hello world","hello world!"),
        ("a  b","a b"),
        ("foo_bar baz","foo_baz baz"),
        ("a/b/c","a/x/c"),
        ("key=value other=1","key=val2 other=1"),
        ("hello, world","hello; world"),
        ("[foo] (bar)","{foo} (bar)"),
        ("onetwo","one two"),
        ("x",""),
        ("","x"),
    ];
 for (a,b) in &cases{
   println!("{:?}->{:?}",a,b);
   println!("  toks A {:?}",a.split_word_bounds().collect::<Vec<_>>());
   println!("  toks B {:?}",b.split_word_bounds().collect::<Vec<_>>());
   let at:Vec<&str>=a.split_word_bounds().collect();
   let bt:Vec<&str>=b.split_word_bounds().collect();
   println!("  diff slice {:?}", diff::slice(&at,&bt));
 }
 let lc=vec![("a\nb\nc\n","c\nb\na\n"),("a\nb\nc\n","x\ny\nz\n"),("one\ntwo\nthree\n","one\nthree\n"),("a\nb\n","x\na\n")];
 for (a,b) in &lc {
   println!("LINES {:?}->{:?}",a,b);
   println!(" diff::lines {:?}",diff::lines(a,b));
   let al:Vec<&str>=a.lines().collect();
   let bl:Vec<&str>=b.lines().collect();
   println!(" diff::slice lines {:?}",diff::slice(&al,&bl));
 }
}
EOF
cd /tmp/difftest && cargo run --offline -q 2>&1 | head -n 250
"}

