use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CommandResultData {
    pub timestamp: String,
    pub command: String,
    pub status: bool,
    pub output: String,
    pub stdout: String,
    pub stderr: String,
}

impl Default for CommandResultData {
    fn default() -> Self {
        Self {
            timestamp: String::new(),
            command: String::new(),
            status: true,
            output: String::new(),
            stdout: String::new(),
            stderr: String::new(),
        }
    }
}

impl CommandResultData {
    pub fn eq_without_timestamp(&self, other: &Self) -> bool {
        self.command == other.command
            && self.status == other.status
            && self.output == other.output
            && self.stdout == other.stdout
            && self.stderr == other.stderr
    }
    pub fn selected<'a>(&'a self, mode: OutputMode) -> &'a str {
        match mode {
            OutputMode::Output => &self.output,
            OutputMode::Stdout => &self.stdout,
            OutputMode::Stderr => &self.stderr,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutputMode {
    Output,
    Stdout,
    Stderr,
}
impl OutputMode {
    pub fn label(self) -> &'static str {
        match self {
            Self::Output => "Output",
            Self::Stdout => "Stdout",
            Self::Stderr => "Stderr",
        }
    }
    pub fn next(self) -> Self {
        match self {
            Self::Output => Self::Stdout,
            Self::Stdout => Self::Stderr,
            Self::Stderr => Self::Output,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DiffMode {
    None,
    Watch,
    Line,
    Word,
}
impl DiffMode {
    pub fn label(self) -> &'static str {
        match self {
            Self::None => "None",
            Self::Watch => "Watch",
            Self::Line => "Line",
            Self::Word => "Word",
        }
    }
    pub fn next(self) -> Self {
        match self {
            Self::None => Self::Watch,
            Self::Watch => Self::Line,
            Self::Line => Self::Word,
            Self::Word => Self::None,
        }
    }
}
