                    style.fg = Some(Color::Indexed(params[i + 2].clamp(0, 255) as u8));
                    i += 2;
                } else if i + 4 < params.len() && params[i + 1] == 2 {
                    style.fg = Some(Color::Rgb(
                        params[i + 2].clamp(0, 255) as u8,
                        params[i + 3].clamp(0, 255) as u8,
                        params[i + 4].clamp(0, 255) as u8,
