const GRAY240: Color = Color::Indexed(240);
const TEAL_NUM: Color = Color::Rgb(56, 119, 120);
const DARKRED_NUM: Color = Color::Rgb(118, 0, 0);

pub fn strip_sgr(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let bytes = s.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == 0x1b && i + 1 < bytes.len() && bytes[i + 1] == b'[' {
            let mut j = i + 2;
            while j < bytes.len() && (bytes[j].is_ascii_digit() || bytes[j] == b';') {
                j += 1;
            }
            if j < bytes.len() && bytes[j] == b'm' {
                i = j + 1;
                continue;
            }
        }
        // push one UTF-8 char
        let ch_len = utf8_len(bytes[i]);
        let end = (i + ch_len).min(bytes.len());
        out.push_str(&s[i..end]);
        i = end;
    }
    out
}
fn utf8_len(b: u8) -> usize {
    if b < 0x80 { 1 } else if b >> 5 == 0b110 { 2 } else if b >> 4 == 0b1110 { 3 } else if b >> 3 == 0b11110 { 4 } else { 1 }
}

// ---------------- ANSI SGR parsing ----------------
#[derive(Clone, Copy, PartialEq)]
struct AnsiStyle {
    fg: Option<Color>,
    bg: Option<Color>,
    mods: Modifier,
}
impl AnsiStyle {
    fn new() -> Self { Self { fg: None, bg: None, mods: Modifier::empty() } }
    fn to_style(self) -> Style {
        let mut st = Style::default();
        if let Some(c) = self.fg { st = st.fg(c); }
        if let Some(c) = self.bg { st = st.bg(c); }
        st = st.add_modifier(self.mods);
        st
    }
}
fn named_color(idx: u8, bright: bool) -> Color {
    match (idx, bright) {
        (0, false) => Color::Black,
        (1, false) => Color::Red,
        (2, false) => Color::Green,
        (3, false) => Color::Yellow,
        (4, false) => Color::Blue,
        (5, false) => Color::Magenta,
        (6, false) => Color::Cyan,
        (7, false) => Color::Gray,
        (0, true) => Color::DarkGray,
        (1, true) => Color::LightRed,
        (2, true) => Color::LightGreen,
        (3, true) => Color::LightYellow,
        (4, true) => Color::LightBlue,
        (5, true) => Color::LightMagenta,
        (6, true) => Color::LightCyan,
        _ => Color::White,
    }
}
fn apply_sgr(style: &mut AnsiStyle, params: &[i64]) {
    if params.is_empty() {
        *style = AnsiStyle::new();
        return;
    }
    let mut i = 0usize;
    while i < params.len() {
        let p = params[i];
        match p {
            0 => *style = AnsiStyle::new(),
            1 => style.mods |= Modifier::BOLD,
            2 => style.mods |= Modifier::DIM,
            3 => style.mods |= Modifier::ITALIC,
            4 => style.mods |= Modifier::UNDERLINED,
            5 => style.mods |= Modifier::SLOW_BLINK,
            6 => style.mods |= Modifier::RAPID_BLINK,
            7 => style.mods |= Modifier::REVERSED,
            8 => style.mods |= Modifier::HIDDEN,
            9 => style.mods |= Modifier::CROSSED_OUT,
            22 => style.mods &= !(Modifier::BOLD | Modifier::DIM),
            23 => style.mods &= !Modifier::ITALIC,
            24 => style.mods &= !Modifier::UNDERLINED,
            25 => style.mods &= !(Modifier::SLOW_BLINK | Modifier::RAPID_BLINK),
            27 => style.mods &= !Modifier::REVERSED,
            28 => style.mods &= !Modifier::HIDDEN,
            29 => style.mods &= !Modifier::CROSSED_OUT,
            30..=37 => style.fg = Some(named_color((p - 30) as u8, false)),
            38 => {
                if i + 2 < params.len() && params[i + 1] == 5 {
                    style.fg = Some(Color::Indexed(params[i + 2].clamp(0, 255) as u8));
                    i += 2;
                } else if i + 4 < params.len() && params[i + 1] == 2 {
                    style.fg = Some(Color::Rgb(
                        params[i + 2].clamp(0, 255) as u8,
                        params[i + 3].clamp(0, 255) as u8,
                        params[i + 4].clamp(0, 255) as u8,
                    ));
                    i += 4;
                }
            }
            39 => style.fg = None,
            40..=47 => style.bg = Some(named_color((p - 40) as u8, false)),
            48 => {
                if i + 2 < params.len() && params[i + 1] == 5 {
                    style.bg = Some(Color::Indexed(params[i + 2].clamp(0, 255) as u8));
                    i += 2;
                } else if i + 4 < params.len() && params[i + 1] == 2 {
                    style.bg = Some(Color::Rgb(
                        params[i + 2].clamp(0, 255) as u8,
                        params[i + 3].clamp(0, 255) as u8,
                        params[i + 4].clamp(0, 255) as u8,
                    ));
                    i += 4;
                }
            }
            49 => style.bg = None,
            90..=97 => style.fg = Some(named_color((p - 90) as u8, true)),
            100..=107 => style.bg = Some(named_color((p - 100) as u8, true)),
            _ => {}
        }
        i += 1;
    }
}

/// Parse ANSI SGR in a whole text. Returns rows split on '\n' (keeping a
/// trailing empty row if text ends with '\n', like split('\n')).
pub fn parse_ansi_rows(text: &str) -> Vec<Vec<Span<'static>>> {
    let mut rows: Vec<Vec<Span<'static>>> = Vec::new();
    let mut cur_row: Vec<Span<'static>> = Vec::new();
    let mut style = AnsiStyle::new();
    let mut cur_text = String::new();
    let mut cur_style = style;
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0usize;
    macro_rules! flush {
        () => {
            if !cur_text.is_empty() {
                cur_row.push(Span::styled(std::mem::take(&mut cur_text), cur_style.to_style()));
            }
        };
    }
    while i < chars.len() {
        let c = chars[i];
        if c == '\x1b' && i + 1 < chars.len() {
            if chars[i + 1] == '[' {
                // CSI
                let mut j = i + 2;
                while j < chars.len() && !('@'..='~').contains(&chars[j]) {
                    j += 1;
                }
                if j < chars.len() {
                    if chars[j] == 'm' {
                        let param_str: String = chars[i + 2..j].iter().collect();
                        let params: Vec<i64> = if param_str.is_empty() {
                            vec![]
                        } else {
                            param_str
                                .split(';')
                                .map(|s| if s.is_empty() { 0 } else { s.parse::<i64>().unwrap_or(0) })
                                .collect()
                        };
                        flush!();
                        apply_sgr(&mut style, &params);
                        cur_style = style;
                    }
                    i = j + 1;
                    continue;
                } else {
                    // incomplete: emit literally
                    cur_text.push(c);
                    i += 1;
                    continue;
                }
            } else if chars[i + 1] == ']' {
                // OSC until BEL or ST
                let mut j = i + 2;
                while j < chars.len() {
                    if chars[j] == '\x07' {
                        j += 1;
                        break;
                    }
                    if chars[j] == '\x1b' && j + 1 < chars.len() && chars[j + 1] == '\\' {
                        j += 2;
                        break;
                    }
                    j += 1;
                }
                i = j;
                continue;
            } else {
                // two-char escape: skip both
                i += 2;
                continue;
            }
        } else if c == '\n' {
            flush!();
            rows.push(std::mem::take(&mut cur_row));
            i += 1;
            continue;
        }
        cur_text.push(c);
        i += 1;
    }
    flush!();
    rows.push(cur_row);
    rows
}

/// Rows for logical `.lines()` content (no trailing empty for text ending
/// in a newline, empty text -> no rows).
fn logical_rows(text: &str) -> Vec<String> {
    text.lines().map(|s| s.to_string()).collect()
}
fn line_has_newline(text: &str, idx: usize, count: usize) -> bool {
    idx + 1 < count || text.ends_with('\n')
}

fn number_spans(num: usize, width: usize, color: Color) -> Vec<Span<'static>> {
    let digits = num.to_string();
    let pad = width.saturating_sub(digits.len());
    let mut v = Vec::new();
    if pad > 0 {
        v.push(Span::raw(" ".repeat(pad)));
    }
    let st = Style::default().fg(color);
    v.push(Span::styled(digits, st));
    v.push(Span::styled(" | ".to_string(), st));
    v
}
fn digits_of(n: usize) -> usize {
    format!("{}", n.max(1)).len()
}

struct TempLine {
    spans: Vec<Span<'static>>,
    num: Option<(usize, Color)>,
}
impl TempLine {
    fn into_line(self, show_num: bool, num_width: usize) -> Line<'static> {
        let mut spans = Vec::new();
        if show_num {
            if let Some((n, c)) = self.num {
                spans.extend(number_spans(n, num_width, c));
            }
        }
        spans.extend(self.spans);
        Line::from(spans)
    }
}

pub fn create_text(after: &CommandResultData, before: &CommandResultData, opt: &TextOptions) -> Text<'static> {
    let cur = after.selected(opt.output_mode);
    let prev = before.selected(opt.output_mode);
    let mut lines: Vec<TempLine> = match opt.diff_mode {
        DiffMode::None => plain_lines(cur, opt.ansi),
        DiffMode::Watch => watch_lines(cur, prev, opt.ansi),
        DiffMode::Line | DiffMode::Word => diff_lines(cur, prev, opt),
    };
    if opt.reverse {
        lines.reverse();
    }
    let num_width = match opt.diff_mode {
        DiffMode::Line | DiffMode::Word => {
            let m = logical_rows(cur).len().max(logical_rows(prev).len());
            digits_of(m)
        }
        _ => digits_of(lines.len()),
    };
    let out: Vec<Line<'static>> = lines
        .into_iter()
        .map(|l| l.into_line(opt.line_number, num_width))
        .collect();
    if out.is_empty() {
        Text::from(Line::from(""))
    } else {
        Text::from(out)
    }
}

fn plain_lines(cur: &str, ansi: bool) -> Vec<TempLine> {
    if ansi {
        parse_ansi_rows(cur)
            .into_iter()
            .enumerate()
            .map(|(i, spans)| TempLine {
                spans: if spans.is_empty() { vec![Span::raw("")] } else { spans },
                num: Some((i + 1, GRAY240)),
            })
            .collect()
    } else {
        cur.split('\n')
            .enumerate()
            .map(|(i, s)| TempLine {
                spans: vec![Span::raw(s.to_string())],
                num: Some((i + 1, GRAY240)),
            })
            .collect()
    }
}

fn watch_lines(cur: &str, prev: &str, ansi: bool) -> Vec<TempLine> {
    // Build per-row Vec<(char, Style)> for cur and prev.
    let cur_rows: Vec<Vec<(char, Style)>>;
    let prev_rows: Vec<Vec<(char, Style)>>;
    if ansi {
        let to_chars = |text: &str| -> Vec<Vec<(char, Style)>> {
            if text.is_empty() {
                return Vec::new();
            }
            let mut rows = parse_ansi_rows(text);
            if text.ends_with('\n') {
                rows.pop();
            }
            rows.into_iter()
                .map(|spans| {
                    let mut v = Vec::new();
                    for sp in spans {
                        for ch in sp.content.chars() {
                            if ch == '\r' { continue; }
                            v.push((ch, sp.style));
                        }
                    }
                    v
                })
                .collect()
        };
        cur_rows = to_chars(cur);
        prev_rows = to_chars(prev);
    } else {
        let to_chars = |text: &str| -> Vec<Vec<(char, Style)>> {
            logical_rows(text)
                .into_iter()
                .map(|l| l.chars().map(|c| (c, Style::default())).collect())
                .collect()
        };
        cur_rows = to_chars(cur);
        prev_rows = to_chars(prev);
    }
    let rows = cur_rows.len().max(prev_rows.len());
    if rows == 0 {
        return vec![TempLine { spans: vec![Span::raw("")], num: Some((1, GRAY240)) }];
    }
    let mut out = Vec::new();
    for i in 0..rows {
        let cur_ex: Option<Vec<(char, Style)>> = cur_rows.get(i).cloned();
        let prev_ex: Option<Vec<(char, Style)>> = prev_rows.get(i).cloned();
        let cur_chars: Vec<(char, Style)> = match &cur_ex {
            Some(v) if v.is_empty() => vec![('\u{200b}', Style::default())],
            Some(v) => v.clone(),
            None => Vec::new(),
        };
        let prev_chars: Vec<(char, Style)> = match &prev_ex {
            Some(v) if v.is_empty() => vec![('\u{200b}', Style::default())],
            Some(v) => v.clone(),
            None => Vec::new(),
        };
        let width = cur_chars.len().max(prev_chars.len());
        let mut spans: Vec<Span<'static>> = Vec::new();
        let mut plain = String::new();
        let mut plain_style = Style::default();
        let mut have_plain = false;
        let mut flush_plain = |spans: &mut Vec<Span<'static>>, plain: &mut String, have: &mut bool, st: Style| {
            if *have && !plain.is_empty() {
                spans.push(Span::styled(std::mem::take(plain), st));
            }
            *have = false;
        };
        for j in 0..width {
            let cur_c = cur_chars.get(j);
            let prev_c = prev_chars.get(j).map(|x| x.0);
            match cur_c {
                Some(&(ch, st)) => {
                    if prev_c == Some(ch) {
                        if have_plain && plain_style != st {
                            flush_plain(&mut spans, &mut plain, &mut have_plain, plain_style);
                        }
                        plain_style = st;
                        have_plain = true;
                        plain.push(ch);
                    } else {
                        flush_plain(&mut spans, &mut plain, &mut have_plain, plain_style);
                        let mut s = st;
                        s = s.add_modifier(Modifier::REVERSED);
                        spans.push(Span::styled(ch.to_string(), s));
                    }
                }
                None => {
                    flush_plain(&mut spans, &mut plain, &mut have_plain, plain_style);
                    spans.push(Span::styled(
                        " ".to_string(),
                        Style::default().add_modifier(Modifier::REVERSED),
                    ));
                }
            }
        }
        flush_plain(&mut spans, &mut plain, &mut have_plain, plain_style);
        if spans.is_empty() {
            spans.push(Span::raw(""));
        }
        out.push(TempLine { spans, num: Some((i + 1, GRAY240)) });
    }
    out
}

// ---------- line / word diff ----------

#[derive(Clone, Copy, PartialEq)]
enum TokKind {
    Common,
    Diff,
}
struct TokSpan {
    run: usize,
    kind: TokKind,
    text: String,
}

fn diff_lines(cur: &str, prev: &str, opt: &TextOptions) -> Vec<TempLine> {
    let cur_lines = logical_rows(cur);
    let prev_lines = logical_rows(prev);
    let cur_refs: Vec<&str> = cur_lines.iter().map(|s| s.as_str()).collect();
    let prev_refs: Vec<&str> = prev_lines.iter().map(|s| s.as_str()).collect();
    // Reverse orientation (new first) matches the reference's LCS choices.
    let results = diff::slice(&cur_refs, &prev_refs);
    // Pre-parse ANSI rows for the TUI colour path (unchanged / pure lines).
    let cur_parsed: Vec<Vec<Span<'static>>> = if opt.ansi {
        let mut r = parse_ansi_rows(cur);
        if cur.ends_with('\n') { r.pop(); }
        r
    } else { Vec::new() };
    let prev_parsed: Vec<Vec<Span<'static>>> = if opt.ansi {
        let mut r = parse_ansi_rows(prev);
        if prev.ends_with('\n') { r.pop(); }
        r
    } else { Vec::new() };

    let red = Style::default().fg(Color::Red);
    let green = Style::default().fg(Color::Green);

    let make_pure = |idx: usize, is_new: bool, parsed: &Vec<Vec<Span<'static>>>, lines_src: &[String]| -> TempLine {
        let (prefix, style, num_color) = if is_new {
            ("+  ", green, TEAL_NUM)
        } else {
            ("-  ", red, DARKRED_NUM)
        };
        let mut spans = vec![Span::styled(prefix.to_string(), style)];
        if opt.ansi {
            if let Some(p) = parsed.get(idx) {
                if p.is_empty() {
                    spans.push(Span::styled(String::new(), style));
                } else {
                    spans.extend(p.iter().cloned());
                }
            } else {
                spans.push(Span::styled(String::new(), style));
            }
        } else {
            spans.push(Span::styled(strip_sgr(&lines_src[idx]), style));
        }
        TempLine { spans, num: Some((idx + 1, num_color)) }
    };

    let mut out: Vec<TempLine> = Vec::new();
    let mut pending_old: Vec<usize> = Vec::new();
    let mut pending_new: Vec<usize> = Vec::new();
    let mut old_idx = 0usize;
    let mut new_idx = 0usize;

    let flush = |pending_old: &mut Vec<usize>, pending_new: &mut Vec<usize>, out: &mut Vec<TempLine>| {
        if pending_old.is_empty() && pending_new.is_empty() {
            return;
        }
        if pending_old.is_empty() {
            if !opt.diff_only || true {
                for &ni in pending_new.iter() {
                    out.push(make_pure(ni, true, &cur_parsed, &cur_lines));
                }
            }
        } else if pending_new.is_empty() {
            for &oi in pending_old.iter() {
                out.push(make_pure(oi, false, &prev_parsed, &prev_lines));
            }
        } else {
            // Replace block: word-token diff over the whole block.
            let render = replace_block(
                prev, cur, &prev_lines, &cur_lines, pending_old, pending_new, opt,
            );
            match render {
                Some(lines) => out.extend(lines),
                None => {
                    for &oi in pending_old.iter() {
                        out.push(make_pure(oi, false, &prev_parsed, &prev_lines));
                    }
                    for &ni in pending_new.iter() {
                        out.push(make_pure(ni, true, &cur_parsed, &cur_lines));
                    }
                }
            }
        }
        pending_old.clear();
        pending_new.clear();
    };

    for r in results {
        match r {
            diff::Result::Left(_) => {
                pending_new.push(new_idx);
                new_idx += 1;
            }
            diff::Result::Right(_) => {
                pending_old.push(old_idx);
                old_idx += 1;
            }
            diff::Result::Both(_, _) => {
                flush(&mut pending_old, &mut pending_new, &mut out);
                if !opt.diff_only {
                    let mut spans = vec![Span::raw("   ".to_string())];
                    if opt.ansi {
                        if let Some(p) = cur_parsed.get(new_idx) {
                            if p.is_empty() {
                                spans.push(Span::raw(""));
                            } else {
                                spans.extend(p.iter().cloned());
                            }
                        } else {
                            spans.push(Span::raw(""));
                        }
                    } else {
                        spans.push(Span::raw(cur_lines[new_idx].clone()));
                    }
                    out.push(TempLine { spans, num: Some((new_idx + 1, GRAY240)) });
                }
                old_idx += 1;
                new_idx += 1;
            }
        }
    }
    flush(&mut pending_old, &mut pending_new, &mut out);
    out
}

fn replace_block(
    prev_text: &str,
    cur_text: &str,
    prev_lines: &[String],
    cur_lines: &[String],
    old_idxs: &[usize],
    new_idxs: &[usize],
    opt: &TextOptions,
) -> Option<Vec<TempLine>> {
    // Build tokens. Token text is stored with its block-local line position.
    struct Tok {
        text: String,
        line_pos: usize,
    }
    let build = |text: &str, lines: &[String], idxs: &[usize]| -> Vec<Tok> {
        let mut toks = Vec::new();
        for (pos, &li) in idxs.iter().enumerate() {
            let content = if opt.ansi { strip_sgr(&lines[li]) } else { lines[li].clone() };
            let mut s = content;
            if line_has_newline(text, li, lines.len()) {
                s.push('\n');
            }
            for t in s.split_word_bounds() {
                toks.push(Tok { text: t.to_string(), line_pos: pos });
            }
        }
        toks
    };
    let old_toks = build(prev_text, prev_lines, old_idxs);
    let new_toks = build(cur_text, cur_lines, new_idxs);
    let old_refs: Vec<&str> = old_toks.iter().map(|t| t.text.as_str()).collect();
    let new_refs: Vec<&str> = new_toks.iter().map(|t| t.text.as_str()).collect();
    let results = diff::slice(&new_refs, &old_refs);
    let both_count = results.iter().filter(|r| matches!(r, diff::Result::Both(..))).count();
    let total = old_toks.len() + new_toks.len();
    let ratio = if total == 0 { 1.0 } else { 2.0 * both_count as f64 / total as f64 };
    if ratio < 0.5 {
        return None;
    }
    // Full word-order reversal of a single line is not emphasised by the
    // reference implementation.
    if old_idxs.len() == 1 && new_idxs.len() == 1 {
        let words = |s: &str| -> Vec<String> {
            s.split_word_bounds()
                .filter(|t| t.chars().any(|c| c.is_alphanumeric()))
                .map(|t| t.to_string())
                .collect()
        };
        let ow = words(&prev_lines[old_idxs[0]]);
        let nw = words(&cur_lines[new_idxs[0]]);
        if ow.len() >= 3 {
            let mut rev = ow.clone();
            rev.reverse();
            if rev == nw {
                return None;
            }
        }
    }
    let mut old_line_spans: Vec<Vec<TokSpan>> = (0..old_idxs.len()).map(|_| Vec::new()).collect();
    let mut new_line_spans: Vec<Vec<TokSpan>> = (0..new_idxs.len()).map(|_| Vec::new()).collect();
    let mut append = |lines: &mut Vec<Vec<TokSpan>>, pos: usize, run: usize, kind: TokKind, text: &str| {
        let text = text.replace('\n', "");
        let line = &mut lines[pos];
        if let Some(last) = line.last_mut() {
            if last.run == run && last.kind == kind {
                last.text.push_str(&text);
                return;
            }
        }
        line.push(TokSpan { run, kind, text });
    };
    let mut old_ptr = 0usize;
    let mut new_ptr = 0usize;
    let mut run = 0usize;
    let mut prev_variant = 255u8;
    for r in &results {
        let variant = match r {
            diff::Result::Left(_) => 0u8,
            diff::Result::Right(_) => 1u8,
            diff::Result::Both(..) => 2u8,
        };
        if variant != prev_variant {
            run += 1;
            prev_variant = variant;
        }
        match r {
            diff::Result::Left(_) => {
                let t = &new_toks[new_ptr];
                append(&mut new_line_spans, t.line_pos, run, TokKind::Diff, &t.text);
                new_ptr += 1;
            }
            diff::Result::Right(_) => {
                let t = &old_toks[old_ptr];
                append(&mut old_line_spans, t.line_pos, run, TokKind::Diff, &t.text);
                old_ptr += 1;
            }
            diff::Result::Both(..) => {
                let ot = &old_toks[old_ptr];
                append(&mut old_line_spans, ot.line_pos, run, TokKind::Common, &ot.text);
                let nt = &new_toks[new_ptr];
                append(&mut new_line_spans, nt.line_pos, run, TokKind::Common, &nt.text);
                old_ptr += 1;
                new_ptr += 1;
            }
        }
    }
    let is_word = opt.diff_mode == DiffMode::Word;
    let mut out = Vec::new();
    for (pos, &oi) in old_idxs.iter().enumerate() {
        let mut spans = vec![Span::styled("-  ".to_string(), Style::default().fg(Color::Red))];
        let toks = &old_line_spans[pos];
        if toks.is_empty() {
            spans.push(Span::styled(String::new(), Style::default().fg(Color::Red)));
        } else {
            for ts in toks {
                let st = match ts.kind {
                    TokKind::Common => Style::default().fg(Color::Red),
                    TokKind::Diff => {
                        if is_word {
                            Style::default().fg(Color::Gray).bg(Color::Red)
                        } else {
                            Style::default().fg(Color::Red)
                        }
                    }
                };
                spans.push(Span::styled(ts.text.clone(), st));
            }
        }
        out.push(TempLine { spans, num: Some((oi + 1, DARKRED_NUM)) });
    }
    for (pos, &ni) in new_idxs.iter().enumerate() {
        let mut spans = vec![Span::styled("+  ".to_string(), Style::default().fg(Color::Green))];
        let toks = &new_line_spans[pos];
        if toks.is_empty() {
            spans.push(Span::styled(String::new(), Style::default().fg(Color::Green)));
        } else {
            for ts in toks {
                let st = match ts.kind {
                    TokKind::Common => Style::default().fg(Color::Green),
                    TokKind::Diff => {
                        if is_word {
                            Style::default().fg(Color::Gray).bg(Color::Green)
                        } else {
                            Style::default().fg(Color::Green)
                        }
                    }
                };
                spans.push(Span::styled(ts.text.clone(), st));
            }
        }
        out.push(TempLine { spans, num: Some((ni + 1, TEAL_NUM)) });
    }
    Some(out)
}

// ---------- summary ----------

#[derive(Clone, Copy, Default)]
pub struct Summary {
    pub line_plus: usize,
    pub line_minus: usize,
    pub char_plus: usize,
    pub char_minus: usize,
}

pub fn summary_counts(before: &str, after: &str, with_char: bool) -> Summary {
    let a_lines: Vec<&str> = after.lines().collect();
    let b_lines: Vec<&str> = before.lines().collect();
    let mut s = Summary::default();
    for r in diff::slice(&a_lines, &b_lines) {
        match r {
            diff::Result::Left(_) => s.line_plus += 1,
            diff::Result::Right(_) => s.line_minus += 1,
            diff::Result::Both(..) => {}
        }
    }
    if with_char {
        for r in diff::chars(after, before) {
            match r {
                diff::Result::Left(_) => s.char_plus += 1,
                diff::Result::Right(_) => s.char_minus += 1,
                diff::Result::Both(..) => {}
            }
        }
    }
    s
}

// ---------- batch ANSI encoding ----------

fn color_param_fg(c: Color) -> Option<String> {
    Some(match c {
        Color::Black => "30".into(),
        Color::Red => "31".into(),
        Color::Green => "32".into(),
        Color::Yellow => "33".into(),
        Color::Blue => "34".into(),
        Color::Magenta => "35".into(),
        Color::Cyan => "36".into(),
        Color::Gray => "37".into(),
        Color::DarkGray => "90".into(),
        Color::LightRed => "91".into(),
        Color::LightGreen => "92".into(),
        Color::LightYellow => "93".into(),
        Color::LightBlue => "94".into(),
        Color::LightMagenta => "95".into(),
        Color::LightCyan => "96".into(),
        Color::White => "97".into(),
        Color::Reset => "39".into(),
        Color::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
        Color::Indexed(n) => format!("38;5;{}", n),
    })
}
fn color_param_bg(c: Color) -> Option<String> {
    Some(match c {
        Color::Black => "40".into(),
        Color::Red => "41".into(),
        Color::Green => "42".into(),
        Color::Yellow => "43".into(),
        Color::Blue => "44".into(),
        Color::Magenta => "45".into(),
        Color::Cyan => "46".into(),
        Color::Gray => "47".into(),
        Color::DarkGray => "100".into(),
        Color::LightRed => "101".into(),
        Color::LightGreen => "102".into(),
        Color::LightYellow => "103".into(),
        Color::LightBlue => "104".into(),
        Color::LightMagenta => "105".into(),
        Color::LightCyan => "106".into(),
        Color::White => "107".into(),
        Color::Reset => "49".into(),
        Color::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
        Color::Indexed(n) => format!("48;5;{}", n),
    })
}

pub fn span_to_ansi(span: &Span<'_>) -> String {
    let st = span.style;
    let mods = st.add_modifier;
    if st.fg.is_none()
        && st.bg.is_none()
        && mods == Modifier::REVERSED
    {
        return format!("\x1b[7m{}\x1b[7m", span.content);
    }
    let mut params: Vec<String> = Vec::new();
    if let Some(bg) = st.bg {
        if let Some(p) = color_param_bg(bg) { params.push(p); }
    }
    if let Some(fg) = st.fg {
        if let Some(p) = color_param_fg(fg) { params.push(p); }
    }
    if mods.contains(Modifier::BOLD) { params.insert(0, "1".into()); }
    if mods.contains(Modifier::DIM) { params.push("2".into()); }
    if mods.contains(Modifier::ITALIC) { params.push("3".into()); }
    if mods.contains(Modifier::UNDERLINED) { params.push("4".into()); }
    if mods.contains(Modifier::SLOW_BLINK) { params.push("5".into()); }
    if mods.contains(Modifier::RAPID_BLINK) { params.push("6".into()); }
    if mods.contains(Modifier::REVERSED) && st.fg.is_none() && st.bg.is_none() {
        params.push("7".into());
    }
    if mods.contains(Modifier::HIDDEN) { params.push("8".into()); }
    if mods.contains(Modifier::CROSSED_OUT) { params.push("9".into()); }
    if params.is_empty() {
        return span.content.to_string();
    }
    format!("\x1b[{}m{}\x1b[0m", params.join(";"), span.content)
}

pub fn line_to_ansi(line: &Line<'_>) -> String {
    let mut out = String::new();
    let mut any_reversed = false;
    for span in &line.spans {
        if span.style.add_modifier.contains(Modifier::REVERSED) {
            any_reversed = true;
        }
        out.push_str(&span_to_ansi(span));
    }
    if any_reversed {
        out.push_str("\x1b[0m");
    }
    out
}

pub fn batch_header(timestamp: &str) -> String {
    let span = Span::styled(
        format!("=====[{}]=========================", timestamp),
        Style::default().fg(GRAY240),
    );
    span_to_ansi(&span)
}
