#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Key {
    pub ctrl: bool,
    pub alt: bool,
    pub shift: bool,
    pub meta: bool,
    pub kind: KeyKind,
}
impl Key {
    pub fn new(kind: KeyKind) -> Self {
        Self { ctrl: false, alt: false, shift: false, meta: false, kind }
    }
    pub fn ch(c: char) -> Self { Self::new(KeyKind::Char(c)) }
    pub fn ctrl(mut self) -> Self { self.ctrl = true; self }
    pub fn alt(mut self) -> Self { self.alt = true; self }
    pub fn shift(mut self) -> Self { self.shift = true; self }

    pub fn parse(raw: &str) -> Option<Self> {
        let lower = raw.trim().to_ascii_lowercase();
        let mouse_kind = match lower.as_str() {
            "mouse-scroll_up" => Some(KeyKind::MouseScrollUp),
            "mouse-scroll_down" => Some(KeyKind::MouseScrollDown),
            "mouse-scroll_left" => Some(KeyKind::MouseScrollLeft),
            "mouse-scroll_right" => Some(KeyKind::MouseScrollRight),
            "mouse-button_down_left" => Some(KeyKind::MouseButtonDownLeft),
            "mouse-button_down_right" => Some(KeyKind::MouseButtonDownRight),
            "mouse-button_up_left" => Some(KeyKind::MouseButtonUpLeft),
            "mouse-button_up_right" => Some(KeyKind::MouseButtonUpRight),
            _ => None,
        };
        if let Some(k) = mouse_kind {
            return Some(Self::new(k));
        }
        let parts: Vec<&str> = lower.split('-').collect();
        if parts.is_empty() {
            return None;
        }
        let base = parts[parts.len() - 1];
        let mut key = Self::new(KeyKind::Char(' '));
        for m in &parts[..parts.len() - 1] {
            match *m {
                "ctrl" => key.ctrl = true,
                "alt" => key.alt = true,
                "shift" => key.shift = true,
                "meta" => key.meta = true,
                _ => {}
            }
        }
        let kind = match base {
            "up" => KeyKind::Up,
            "down" => KeyKind::Down,
            "left" => KeyKind::Left,
            "right" => KeyKind::Right,
            "home" => KeyKind::Home,
            "end" => KeyKind::End,
            "pageup" => KeyKind::PageUp,
            "pagedown" => KeyKind::PageDown,
            "backspace" => KeyKind::Backspace,
            "delete" | "del" => KeyKind::Delete,
            "insert" | "ins" => KeyKind::Insert,
            "tab" => KeyKind::Tab,
            "backtab" => {
                key.shift = true;
                KeyKind::Tab
            }
            "enter" => KeyKind::Enter,
            "esc" => KeyKind::Esc,
            "space" => KeyKind::Char(' '),
            "minus" | "hyphen" => KeyKind::Char('-'),
            "equal" => KeyKind::Char('='),
            "plus" => KeyKind::Char('+'),
            _ => {
                if let Some(rest) = base.strip_prefix('f') {
                    if let Ok(n) = rest.parse::<u8>() {
                        if (1..=12).contains(&n) && rest.len() == format!("{}", n).len() {
                            key.kind = KeyKind::F(n);
                            return Some(key);
                        }
                    }
                }
                let chars: Vec<char> = base.chars().collect();
                if chars.len() == 2 && chars[0] == '\\' {
                    KeyKind::Char(chars[1])
                } else if chars.len() == 1 {
                    let c = chars[0];
                    if !c.is_ascii() || c.is_control() {
                        return None;
                    }
                    if lower.len() == 1 && matches!(c, ':' | '[' | '\\' | '-') {
                        return None;
                    }
                    if c == ':' || c == '-' {
                        return None;
                    }
                    KeyKind::Char(c)
                } else {
                    return None;
                }
            }
        };
        key.kind = kind;
        Some(key)
    }
}
impl fmt::Display for Key {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let base = match self.kind {
            KeyKind::Char(' ') => "space".to_string(),
            KeyKind::Char(c) => c.to_string(),
            KeyKind::Up => "up".into(),
            KeyKind::Down => "down".into(),
            KeyKind::Left => "left".into(),
            KeyKind::Right => "right".into(),
            KeyKind::Home => "home".into(),
            KeyKind::End => "end".into(),
            KeyKind::PageUp => "pageup".into(),
            KeyKind::PageDown => "pagedown".into(),
            KeyKind::Backspace => "backspace".into(),
            KeyKind::Delete => "delete".into(),
            KeyKind::Insert => "insert".into(),
            KeyKind::Tab => {
                if self.shift && !self.ctrl && !self.alt && !self.meta {
                    return write!(f, "backtab");
                }
                "tab".into()
            }
            KeyKind::Enter => "enter".into(),
            KeyKind::Esc => "esc".into(),
            KeyKind::F(n) => format!("f{}", n),
            KeyKind::MouseScrollUp => return write!(f, "mouse-scroll_up"),
            KeyKind::MouseScrollDown => return write!(f, "mouse-scroll_down"),
            KeyKind::MouseScrollLeft => return write!(f, "mouse-scroll_left"),
            KeyKind::MouseScrollRight => return write!(f, "mouse-scroll_right"),
            KeyKind::MouseButtonDownLeft => return write!(f, "mouse-button_down_left"),
            KeyKind::MouseButtonDownRight => return write!(f, "mouse-button_down_right"),
            KeyKind::MouseButtonUpLeft => return write!(f, "mouse-button_up_left"),
            KeyKind::MouseButtonUpRight => return write!(f, "mouse-button_up_right"),
        };
        let mut parts: Vec<&str> = Vec::new();
        if self.shift && !(self.kind == KeyKind::Tab) {
            parts.push("shift");
        }
        if self.ctrl { parts.push("ctrl"); }
        if self.alt { parts.push("alt"); }
        if self.meta { parts.push("meta"); }
        if self.kind == KeyKind::Tab && self.shift {
            // handled above only for the plain case; with other modifiers include shift
            if self.ctrl || self.alt || self.meta {
                parts.insert(0, "shift");
            }
        }
        if parts.is_empty() {
            write!(f, "{}", base)
        } else {
            write!(f, "{}-{}", parts.join("-"), base)
        }
    }
}

pub fn parse_keymap_entry(s: &str) -> Option<Option<(Key, Action)>> {
    if s.trim().is_empty() {
        return Some(None);
    }
    // Find the first unescaped '=' or ':'.
    let bytes = s.as_bytes();
    let mut i = 0usize;
    let mut sep: Option<usize> = None;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => {
                i += 2;
                continue;
            }
            b'=' | b':' => {
                sep = Some(i);
                break;
            }
            _ => {}
        }
        i += 1;
    }
    let sep = sep?;
    let key_raw = s[..sep].trim();
    let action_raw = s[sep + 1..].trim();
    if key_raw.is_empty() || action_raw.is_empty() {
        return None;
    }
    let key = Key::parse(key_raw)?;
    let action = Action::parse(action_raw)?;
    Some(Some((key, action)))
}

pub type Keymap = BTreeMap<Key, Action>;

pub fn default_keymap() -> Keymap {
    let mut m: Keymap = BTreeMap::new();
    let mut add = |k: Key, a: Action, m: &mut Keymap| {
        m.insert(k, a);
    };
    add(Key::new(KeyKind::Up), Action::Up, &mut m);
    add(Key::new(KeyKind::Down), Action::Down, &mut m);
    add(Key::new(KeyKind::Right).alt(), Action::ScrollRight, &mut m);
    add(Key::new(KeyKind::Right).alt().shift(), Action::ScrollHorizontalEnd, &mut m);
    add(Key::new(KeyKind::Left).alt(), Action::ScrollLeft, &mut m);
    add(Key::new(KeyKind::Left).alt().shift(), Action::ScrollHorizontalHome, &mut m);
    add(Key::new(KeyKind::PageUp), Action::PageUp, &mut m);
    add(Key::new(KeyKind::PageDown), Action::PageDown, &mut m);
    add(Key::new(KeyKind::Home), Action::MoveTop, &mut m);
    add(Key::new(KeyKind::End), Action::MoveEnd, &mut m);
    add(Key::new(KeyKind::Tab), Action::ToggleForcus, &mut m);
    add(Key::new(KeyKind::Left), Action::ForcusWatchPane, &mut m);
    add(Key::new(KeyKind::Right), Action::ForcusHistoryPane, &mut m);
    add(Key::ch('q'), Action::Quit, &mut m);
    add(Key::new(KeyKind::Esc), Action::Reset, &mut m);
    add(Key::ch('c').ctrl(), Action::Cancel, &mut m);
    add(Key::ch('h'), Action::Help, &mut m);
    add(Key::ch('c'), Action::ToggleColor, &mut m);
    add(Key::ch('n'), Action::ToggleLineNumber, &mut m);
    add(Key::ch('r'), Action::ToggleReverse, &mut m);
    add(Key::ch('m'), Action::ToggleMouseSupport, &mut m);
    add(Key::ch('t'), Action::ToggleViewHeaderPane, &mut m);
    add(Key::new(KeyKind::Backspace), Action::ToggleViewHistoryPane, &mut m);
    add(Key::ch('b'), Action::ToggleBorder, &mut m);
    add(Key::ch('d'), Action::ToggleDiffMode, &mut m);
    add(Key::ch('0'), Action::SetDiffModePlane, &mut m);
    add(Key::ch('1'), Action::SetDiffModeWatch, &mut m);
    add(Key::ch('2'), Action::SetDiffModeLine, &mut m);
    add(Key::ch('3'), Action::SetDiffModeWord, &mut m);
    add(Key::ch('o').shift(), Action::SetDiffOnly, &mut m);
    add(Key::ch('o'), Action::ToggleOutputMode, &mut m);
    add(Key::new(KeyKind::F(3)), Action::SetOutputModeOutput, &mut m);
    add(Key::new(KeyKind::F(1)), Action::SetOutputModeStdout, &mut m);
    add(Key::new(KeyKind::F(2)), Action::SetOutputModeStderr, &mut m);
    add(Key::ch('w'), Action::ToggleWrapMode, &mut m);
    add(Key::ch('n').ctrl(), Action::NextKeyword, &mut m);
    add(Key::ch('p').ctrl(), Action::PrevKeyword, &mut m);
    add(Key::ch('s').shift(), Action::ToggleHistorySummary, &mut m);
    add(Key::ch('+'), Action::IntervalPlus, &mut m);
    add(Key::ch('-'), Action::IntervalMinus, &mut m);
    add(Key::ch('p'), Action::TogglePause, &mut m);
    add(Key::ch('/'), Action::ChangeFilterMode, &mut m);
    add(Key::ch('*'), Action::ChangeRegexFilterMode, &mut m);
    add(Key::new(KeyKind::MouseScrollUp), Action::MouseScrollUp, &mut m);
    add(Key::new(KeyKind::MouseScrollDown), Action::MouseScrollDown, &mut m);
    add(Key::new(KeyKind::MouseButtonDownLeft), Action::MouseButtonLeft, &mut m);
    m
}
EOF
