fn custom_error(msg: String) -> ! {
    build_cli()
        .error(clap::error::ErrorKind::InvalidValue, msg)
        .exit()
}

fn prompt_same_file() {
    let stdin = std::io::stdin();
    loop {
        print!("Log to the same file? (Y/n) ");
        let _ = std::io::stdout().flush();
        let mut line = String::new();
        match stdin.lock().read_line(&mut line) {
            Ok(_) => match line.trim().to_ascii_lowercase().as_str() {
                "" | "y" | "yes" => break,
                "n" | "no" => std::process::exit(1),
                _ => continue,
            },
            Err(_) => continue,
        }
    }
}

struct LoadedLog {
    history: Vec<CommandResultData>,
    last: Option<CommandResultData>,
}

struct FailingReader {
    err: Option<std::io::Error>,
}
impl Read for FailingReader {
    fn read(&mut self, _buf: &mut [u8]) -> std::io::Result<usize> {
        Err(self.err.take().unwrap_or_else(|| std::io::Error::new(std::io::ErrorKind::Other, "error")))
    }
}

fn load_logfile(path_str: &str) -> LoadedLog {
    let path = Path::new(path_str);
    let parent = path.parent().unwrap();
    let current = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let dir = current.join(parent);
    if !dir.exists() {
        custom_error(format!("directory \"{}\" is not exists.", dir.display()));
    }
    if !path.exists() {
        return LoadedLog { history: Vec::new(), last: None };
    }
    if let Ok(md) = std::fs::metadata(path) {
        if md.len() == 0 {
            eprintln!("file \"{}\" is exists and empty.", path_str);
            prompt_same_file();
            return LoadedLog { history: Vec::new(), last: None };
        }
    }
    // Attempt to open / stream-parse.
    let mut parse_error: Option<serde_json::Error> = None;
    let mut history: Vec<CommandResultData> = Vec::new();
    let mut last: Option<CommandResultData> = None;
    match std::fs::File::open(path) {
        Ok(file) => {
            let reader = BufReader::new(file);
            let stream = serde_json::Deserializer::from_reader(reader)
                .into_iter::<CommandResultData>();
            let mut before: Option<CommandResultData> = None;
            for item in stream {
                match item {
                    Ok(rec) => {
                        last = Some(rec.clone());
                        let is_dup = match &before {
                            Some(b) => rec.eq_without_timestamp(b),
                            None => false,
                        };
                        if !is_dup {
                            history.push(rec.clone());
                        }
                        before = Some(rec);
                    }
                    Err(e) => {
                        parse_error = Some(e);
                        break;
                    }
                }
            }
        }
        Err(e) => {
            // Reproduce serde_json's rendering of an underlying io error.
            let kind = e.kind();
            let raw = e.raw_os_error();
            let io_err = match raw {
                Some(code) => std::io::Error::from_raw_os_error(code),
                None => std::io::Error::new(kind, e.to_string()),
            };
            let r = FailingReader { err: Some(io_err) };
            let res: Result<CommandResultData, _> = serde_json::from_reader(r);
            if let Err(se) = res {
                parse_error = Some(se);
            }
        }
    }
    if let Some(e) = parse_error {
        eprintln!("file \"{}\" is exists and json parse error.", path_str);
        eprintln!("{:?}", e);
        prompt_same_file();
        return LoadedLog { history: Vec::new(), last: None };
    }
    LoadedLog { history, last }
}

pub fn append_log(path: &str, result: &CommandResultData) {
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
        if let Ok(s) = serde_json::to_string(result) {
            let _ = writeln!(f, "{}", s);
        }
    }
}

#[derive(Serialize)]
struct HwatchData<'a> {
    before_result: &'a CommandResultData,
    after_result: &'a CommandResultData,
}

pub fn spawn_aftercommand(cmd: &str, before: &CommandResultData, after: &CommandResultData) {
    let data = serde_json::to_string(&HwatchData {
        before_result: before,
        after_result: after,
    })
    .unwrap_or_default();
    let _ = ProcCommand::new("sh")
        .arg("-c")
        .arg(cmd)
        .env("HWATCH_DATA", data)
        .spawn();
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    let mut full_args: Vec<String> = Vec::new();
    if !raw_args.is_empty() {
        full_args.push(raw_args[0].clone());
    }
    if let Ok(h) = std::env::var("HWATCH") {
        full_args.extend(h.split_whitespace().map(|s| s.to_string()));
    }
    full_args.extend(raw_args.iter().skip(1).cloned());
    let matches = build_cli().get_matches_from(full_args);

    // Logfile loading (performed before most other validation).
    let logfile_val: Option<String> = matches.get_one::<String>("logfile").cloned();
    let loaded = if let Some(ref lf) = logfile_val {
        load_logfile(lf)
    } else {
        LoadedLog { history: Vec::new(), last: None }
    };

    // Output mode (unwrap mirrors the reference panic for `-o` with no value).
    let output_str: &String = matches.get_one::<String>("output").unwrap();
    let output_mode = match output_str.as_str() {
        "stdout" => OutputMode::Stdout,
        "stderr" => OutputMode::Stderr,
        _ => OutputMode::Output,
    };

    // Keymap parsing.
    let mut keymap = keymap::default_keymap();
    if let Some(vals) = matches.get_many::<String>("keymap") {
        for v in vals {
            match keymap::parse_keymap_entry(v) {
                Some(Some((k, a))) => {
                    keymap.insert(k, a);
                }
                Some(None) => {}
                None => {
                    eprint!("Failed to parse keymap.\n");
                    std::process::exit(1);
                }
            }
        }
    }

    // Command determination.
    let command_vec: Vec<String> = matches
        .get_many::<String>("command")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let command: String = if !command_vec.is_empty() {
        command_vec.join(" ")
    } else if let Some(ref last) = loaded.last {
        last.command.clone()
    } else {
        custom_error("command not specified and logfile is empty.".to_string());
    };

    let diff_mode = match matches.get_one::<String>("differences").map(|s| s.as_str()) {
        Some("watch") => DiffMode::Watch,
        Some("line") => DiffMode::Line,
        Some("word") => DiffMode::Word,
        _ => DiffMode::None,
    };

    let config = AppConfig {
        batch: matches.get_flag("batch"),
        beep: matches.get_flag("beep"),
        border: matches.get_flag("border"),
        with_scrollbar: matches.get_flag("with-scrollbar"),
        mouse: matches.get_flag("mouse"),
        color: matches.get_flag("color"),
        reverse: matches.get_flag("reverse"),
        compress: matches.get_flag("compress"),
        no_title: matches.get_flag("no-title"),
        enable_summary_char: matches.get_flag("enable-summary-char"),
        line_number: matches.get_flag("line-number"),
        no_help_banner: matches.get_flag("no-help-banner"),
        no_summary: matches.get_flag("no-summary"),
        is_exec: matches.get_flag("exec"),
        diff_output_only: matches.get_flag("diff-output-only"),
        after_command: matches.get_one::<String>("aftercommand").cloned(),
        logfile: logfile_val,
        shell: matches.get_one::<String>("shell").cloned().unwrap_or_else(|| "sh -c".to_string()),
        interval: *matches.get_one::<f64>("interval").unwrap_or(&2.0),
        precise: matches.get_flag("precise"),
        limit: *matches.get_one::<u32>("limit").unwrap_or(&5000),
        tab_size: *matches.get_one::<u16>("tab-size").unwrap_or(&4),
        diff_mode,
        output_mode,
        keymap,
        command,
    };

    if config.batch {
        run_batch(config);
    } else {
        std::process::exit(app::run(config, loaded.history, loaded.last));
    }
}

fn run_batch(config: AppConfig) {
    let (tx, rx) = mpsc::channel::<CommandResultData>();
    let exec_cfg = Arc::new(exec::ExecConfig {
        command: config.command.clone(),
        shell: config.shell.clone(),
        is_exec: config.is_exec,
    });
    let interval = Arc::new(Mutex::new(config.interval));
    let paused = Arc::new(Mutex::new(false));
    exec::spawn_exec_thread(exec_cfg, interval, paused, config.precise, tx);
    let opt = textgen::TextOptions {
        diff_mode: config.diff_mode,
        diff_only: config.diff_output_only,
        line_number: config.line_number,
        reverse: config.reverse,
        output_mode: config.output_mode,
        ansi: false,
    };
    let mut before = CommandResultData::default();
    while let Ok(result) = rx.recv() {
        if !result.eq_without_timestamp(&before) {
            let text = textgen::create_text(&result, &before, &opt);
            println!("{}", textgen::batch_header(&result.timestamp));
            for line in &text.lines {
                println!("{}", textgen::line_to_ansi(line));
            }
            if config.beep {
                println!("\u{7}");
            }
            if let Some(ref lf) = config.logfile {
                append_log(lf, &before);
            }
            if let Some(ref ac) = config.after_command {
                spawn_aftercommand(ac, &before, &result);
            }
            before = result;
        }
    }
}
