fn load_logfile(path_str: &str) -> LoadedLog {
    let path = Path::new(path_str);
    let parent = path.parent().unwrap();
    let current = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let dir = current.join(parent);
    if !dir.exists() {
        custom_error(format!("directory \"{}\" is not exists.", dir.display()));
    }
    if !path.exists() {
        return LoadedLog { history: Vec::new(), last: None };
    }
    if let Ok(md) = std::fs::metadata(path) {
        if md.len() == 0 {
            eprintln!("file \"{}\" is exists and empty.", path_str);
            prompt_same_file();
            return LoadedLog { history: Vec::new(), last: None };
        }
    }
    // Attempt to open / stream-parse.
    let mut parse_error: Option<serde_json::Error> = None;
    let mut history: Vec<CommandResultData> = Vec::new();
    let mut last: Option<CommandResultData> = None;
    match std::fs::File::open(path) {
        Ok(file) => {
            let reader = BufReader::new(file);
            let stream = serde_json::Deserializer::from_reader(reader)
                .into_iter::<CommandResultData>();
            let mut before: Option<CommandResultData> = None;
            for item in stream {
                match item {
                    Ok(rec) => {
                        last = Some(rec.clone());
                        let is_dup = match &before {
                            Some(b) => rec.eq_without_timestamp(b),
                            None => false,
                        };
                        if !is_dup {
                            history.push(rec.clone());
                        }
                        before = Some(rec);
                    }
                    Err(e) => {
                        parse_error = Some(e);
                        break;
                    }
                }
            }
        }
        Err(e) => {
            // Reproduce serde_json's rendering of an underlying io error.
            let kind = e.kind();
            let raw = e.raw_os_error();
            let io_err = match raw {
                Some(code) => std::io::Error::from_raw_os_error(code),
                None => std::io::Error::new(kind, e.to_string()),
            };
            let r = FailingReader { err: Some(io_err) };
            let res: Result<CommandResultData, _> = serde_json::from_reader(r);
            if let Err(se) = res {
                parse_error = Some(se);
            }
        }
    }
    if let Some(e) = parse_error {
        eprintln!("file \"{}\" is exists and json parse error.", path_str);
        eprintln!("{:?}", e);
        prompt_same_file();
        return LoadedLog { history: Vec::new(), last: None };
    }
    LoadedLog { history, last }
}

pub fn append_log(path: &str, result: &CommandResultData) {
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
