    }
    if let Ok(h) = std::env::var("HWATCH") {
        full_args.extend(h.split_whitespace().map(|s| s.to_string()));
    }
    full_args.extend(raw_args.iter().skip(1).cloned());
    let matches = build_cli().get_matches_from(full_args);

    // Logfile loading (performed before most other validation).
    let logfile_val: Option<String> = matches.get_one::<String>("logfile").cloned();
    let loaded = if let Some(ref lf) = logfile_val {
        load_logfile(lf)
    } else {
        LoadedLog { history: Vec::new(), last: None }
    };

    // Output mode (unwrap mirrors the reference panic for `-o` with no value).
    let output_str: &String = matches.get_one::<String>("output").unwrap();
    let output_mode = match output_str.as_str() {
        "stdout" => OutputMode::Stdout,
        "stderr" => OutputMode::Stderr,
        _ => OutputMode::Output,
    };

    // Keymap parsing.
    let mut keymap = keymap::default_keymap();
    if let Some(vals) = matches.get_many::<String>("keymap") {
        for v in vals {
            match keymap::parse_keymap_entry(v) {
                Some(Some((k, a))) => {
                    keymap.insert(k, a);
                }
                Some(None) => {}
                None => {
                    eprint!("Failed to parse keymap.\n");
                    std::process::exit(1);
                }
            }
        }
    }

    // Command determination.
    let command_vec: Vec<String> = matches
        .get_many::<String>("command")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let command: String = if !command_vec.is_empty() {
        command_vec.join(" ")
    } else if let Some(ref last) = loaded.last {
        last.command.clone()
    } else {
        custom_error("command not specified and logfile is empty.".to_string());
    };

    let diff_mode = match matches.get_one::<String>("differences").map(|s| s.as_str()) {
        Some("watch") => DiffMode::Watch,
        Some("line") => DiffMode::Line,
        Some("word") => DiffMode::Word,
        _ => DiffMode::None,
    };

    let config = AppConfig {
        batch: matches.get_flag("batch"),
        beep: matches.get_flag("beep"),
        border: matches.get_flag("border"),
        with_scrollbar: matches.get_flag("with-scrollbar"),
        mouse: matches.get_flag("mouse"),
        color: matches.get_flag("color"),
        reverse: matches.get_flag("reverse"),
        compress: matches.get_flag("compress"),
        no_title: matches.get_flag("no-title"),
        enable_summary_char: matches.get_flag("enable-summary-char"),
        line_number: matches.get_flag("line-number"),
        no_help_banner: matches.get_flag("no-help-banner"),
        no_summary: matches.get_flag("no-summary"),
        is_exec: matches.get_flag("exec"),
        diff_output_only: matches.get_flag("diff-output-only"),
        after_command: matches.get_one::<String>("aftercommand").cloned(),
        logfile: logfile_val,
        shell: matches.get_one::<String>("shell").cloned().unwrap_or_else(|| "sh -c".to_string()),
