        run_batch(config);
    } else {
        std::process::exit(app::run(config, loaded.history, loaded.last));
    }
}

fn run_batch(config: AppConfig) {
    let (tx, rx) = mpsc::channel::<CommandResultData>();
    let exec_cfg = Arc::new(exec::ExecConfig {
        command: config.command.clone(),
        shell: config.shell.clone(),
        is_exec: config.is_exec,
    });
    let interval = Arc::new(Mutex::new(config.interval));
    let paused = Arc::new(Mutex::new(false));
    exec::spawn_exec_thread(exec_cfg, interval, paused, config.precise, tx);
    let opt = textgen::TextOptions {
        diff_mode: config.diff_mode,
        diff_only: config.diff_output_only,
        line_number: config.line_number,
        reverse: config.reverse,
        output_mode: config.output_mode,
        ansi: false,
    };
    let mut before = CommandResultData::default();
    while let Ok(result) = rx.recv() {
        if !result.eq_without_timestamp(&before) {
            let text = textgen::create_text(&result, &before, &opt);
            println!("{}", textgen::batch_header(&result.timestamp));
            for line in &text.lines {
                println!("{}", textgen::line_to_ansi(line));
            }
            if config.beep {
                println!("\u{7}");
            }
            if let Some(ref lf) = config.logfile {
                append_log(lf, &before);
            }
            if let Some(ref ac) = config.after_command {
                spawn_aftercommand(ac, &before, &result);
            }
            before = result;
        }
    }
}
