{"command":"cat > /tmp/difftest/src/main.rs <<'EOF'
use unicode_segmentation::UnicodeSegmentation;
#[derive(Debug,Clone,Copy,PartialEq)]
enum Op{Eq(usize),Del(usize),Ins(usize)} // index in old for Eq/Del, in new for Ins (Eq displays old)
fn myers(a:&[&str],b:&[&str], prefer_down:bool)->Vec<Op>{
 let n=a.len() as i32;let m=b.len() as i32;let max=n+m;
 let offset=max;
 let mut vs:Vec<Vec<i32>>=Vec::new();
 let mut v=vec![0i32;(2*max+1) as usize];
 let mut found_d=None;
 for d in 0..=max{
  vs.push(v.clone());
  let mut k=-d;
  while k<=d{
   let idx=(k+offset) as usize;
   let mut x=if k==-d || (k!=d && ((prefer_down && v[idx-1]<=v[idx+1]) || (!prefer_down && v[idx-1]<v[idx+1]))) {v[idx+1]} else {v[idx-1]+1};
   let mut y=x-k;
   while x<n && y<m && a[x as usize]==b[y as usize]{x+=1;y+=1;}
   v[idx]=x;
   if x>=n && y>=m{found_d=Some(d);}
   k+=2;
  }
  if found_d.is_some(){break;}
 }
 let d_end=found_d.unwrap();
 // backtrack
 let mut x=n;let mut y=m;let mut ops=Vec::new();
 for d in (0..=d_end).rev(){
   let vprev=&vs[d as usize]; // careful: vs[d] is V before iteration d (we pushed at start)
   let k=x-y;let idx=(k+offset) as usize;
   // determine if previous step was down or right using vprev
   let prev_k=if k==-d || (k!=d && ((prefer_down && vprev[idx-1]<=vprev[idx+1]) || (!prefer_down && vprev[idx-1]<vprev[idx+1]))) {k+1} else {k-1};
   let prev_x=vprev[(prev_k+offset) as usize];
   let prev_y=prev_x-prev_k;
   // snake from (prev point adjusted) to (x,y): Actually after the single edit step, snake goes to current.
   // The edit step endpoint:
   let (mut sx,mut sy)=if prev_k>k {
      // down: x = prev_x, y=prev_y+1? Wait down in graph: k decreases by1, x same, y+1
      (prev_x, prev_y+1)
   } else {
      (prev_x+1, prev_y)
   };
   // Push snake eq in reverse
   while x>sx && y>sy {x-=1;y-=1;ops.push(Op::Eq(x as usize));}
   if d==0{break;}
   if prev_k>k {
      // insertion of b[sy-1]
      y-=1;ops.push(Op::Ins(y as usize));
   } else {
      x-=1;ops.push(Op::Del(x as usize));
   }
   // now x,y should equal prev_x,prev_y
   // continue loop
 }
 ops.reverse();ops
}
fn show(a:&str,b:&str){
 let at:Vec<&str>=a.split_word_bounds().collect();let bt:Vec<&str>=b.split_word_bounds().collect();
 for pref in [true,false]{
  let ops=myers(&at,&bt,pref);
  let mut oi=0;let mut s=String::new();
  for op in &ops{match *op{Op::Eq(i)=>{s+=&format!("Eq({:?}) ",at[i]);oi+=1;}Op::Del(i)=>s+=&format!("Del({:?}) ",at[i]),Op::Ins(j)=>s+=&format!("Ins({:?}) ",bt[j])}}
  println!("pref {}: {}",pref,s);
 }
}
fn main(){
 show("old one here\nold two here\n","new one here\n");
 show("a1 b\nc2 d\ne3 f\n","x1 b\ny2 f\n");
 show("hello world foo\n","hello brave world\n");
 show("a b c\n","c b a\n");
 show("hello world this is\n","hello this is world\n");
}
EOF
cd /tmp/difftest && cargo run --offline -q 2>&1 | head -n 100
"}

