}

pub fn run(config: AppConfig, loaded: Vec<CommandResultData>, last: Option<CommandResultData>) -> i32 {
    let (tx, rx) = mpsc::channel::<CommandResultData>();
    let interval_shared = Arc::new(Mutex::new(config.interval));
    let paused_shared = Arc::new(Mutex::new(false));
    let exec_cfg = Arc::new(exec::ExecConfig {
        command: config.command.clone(),
        shell: config.shell.clone(),
        is_exec: config.is_exec,
    });
    let _tx_keepalive = tx.clone();
    exec::spawn_exec_thread(
        exec_cfg,
        interval_shared.clone(),
        paused_shared.clone(),
        config.precise,
        tx,
    );

    if enable_raw_mode().is_err() {
        return 0;
    }
    let mut out = stdout();
    let _ = execute!(out, EnterAlternateScreen);
    if config.mouse {
        let _ = execute!(out, crossterm::event::EnableMouseCapture);
    } else {
        let _ = execute!(out, crossterm::event::DisableMouseCapture);
    }
    let backend = CrosstermBackend::new(out);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            return 0;
        }
    };
    let _ = terminal.clear();
    let _ = terminal.hide_cursor();

    let mut app = App {
        show_title: !config.no_title,
        show_history: true,
        cfg: config,
        history: loaded,
        latest: last,
        selection: None,
        focus: Focus::History,
        watch_scroll_y: 0,
        watch_scroll_x: 0,
        history_scroll_y: 0,
        help_scroll: 0,
        popup: Popup::None,
        show_summary: false,
        wrap: true,
        filter: FilterState::new(),
        summaries: HashMap::new(),
        should_quit: false,
        pending_beep: false,
        last_watch_area: Rect::default(),
        last_history_area: Rect::default(),
        last_frame_size: Rect::default(),
        last_help_inner_h: 0,
        header_width: 0,
        header_dirty: false,
        interval_shared,
        paused_shared,
    };

    let mut dirty = true;
    loop {
        // Drain exec results.
        while let Ok(result) = rx.try_recv() {
            app.on_result(result);
            dirty = true;
        }
        if dirty {
            if terminal.draw(|f| app.draw(f)).is_err() {
                break;
            }
            if app.pending_beep {
                let _ = terminal.backend_mut().write_all(b"\x07");
                let _ = terminal.backend_mut().flush();
                app.pending_beep = false;
            }
            dirty = false;
        }
        if app.should_quit {
            break;
        }
        match event::poll(Duration::from_millis(20)) {
            Ok(true) => {
                if let Ok(ev) = event::read() {
                    app.handle_event(ev);
                    dirty = true;
                    if app.should_quit {
                        break;
                    }
                }
            }
            Ok(false) => {}
            Err(_) => break,
        }
    }

    let _ = terminal.show_cursor();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = execute!(terminal.backend_mut(), crossterm::event::DisableMouseCapture);
    let _ = disable_raw_mode();
    0
}

impl App {
    fn on_result(&mut self, result: CommandResultData) {
        let is_changed = match self.history.last() {
            Some(last) => !result.eq_without_timestamp(last),
            None => !result.eq_without_timestamp(&CommandResultData::default()),
        };
        if !is_changed {
            return;
        }
        let before = self
            .history
            .last()
            .cloned()
            .unwrap_or_default();
        self.latest = Some(result.clone());
        self.history.push(result.clone());
        // Prune to limit.
        if self.cfg.limit > 0 {
            while self.history.len() > self.cfg.limit as usize {
                self.history.remove(0);
                self.summaries.clear();
                if let Some(pos) = self.selection {
                    // selection is positional from the newest; pruning the
                    // oldest shifts nothing unless it removed the selected one.
                    let disp_len = self.displayed_indices().len();
                    if pos >= disp_len {
                        self.selection = None;
                    }
                }
            }
        }
        if let Some(ref lf) = self.cfg.logfile {
            append_log(lf, &result);
        }
        if let Some(ref ac) = self.cfg.after_command {
            spawn_aftercommand(ac, &before, &result);
        }
        if self.cfg.beep {
            self.pending_beep = true;
        }
        self.header_dirty = true;
    }

    fn selected_result(&self) -> (CommandResultData, CommandResultData) {
        // Returns (after, before) for text generation.
        let target = match self.selection {
            None => self
                .latest
                .clone()
                .or_else(|| self.history.last().cloned())
                .unwrap_or_default(),
            Some(pos) => {
                let idxs = self.displayed_indices();
                if let Some(&hi) = idxs.get(pos) {
                    self.history[hi].clone()
                } else {
                    self.latest.clone().unwrap_or_default()
                }
            }
        };
        // Find the position of target in history (by identity of the entry
        // it corresponds to) to locate its predecessor.
        let before = match self.selection {
            None => {
                // Latest corresponds to the last history entry.
                if self.history.len() >= 2 {
                    self.history[self.history.len() - 2].clone()
                } else {
                    target.clone()
                }
            }
            Some(pos) => {
                let idxs = self.displayed_indices();
                if let Some(&hi) = idxs.get(pos) {
                    if hi > 0 {
                        self.history[hi - 1].clone()
                    } else {
                        target.clone()
                    }
                } else {
                    target.clone()
                }
            }
        };
        (target, before)
    }

    fn displayed_indices(&self) -> Vec<usize> {
        let mut out = Vec::new();
        for idx in (0..self.history.len()).rev() {
            let entry = &self.history[idx];
            // Output-mode filter.
            match self.cfg.output_mode {
                OutputMode::Output => {}
                OutputMode::Stdout => {
                    let prev = if idx > 0 { self.history[idx - 1].stdout.as_str() } else { "" };
                    if entry.stdout == prev {
                        continue;
                    }
                }
                OutputMode::Stderr => {
                    let prev = if idx > 0 { self.history[idx - 1].stderr.as_str() } else { "" };
                    if entry.stderr == prev {
                        continue;
                    }
                }
            }
            // Keyword / regex filter.
            if self.filter.active() {
                let text = entry.selected(self.cfg.output_mode);
                let ok = match self.filter.typ {
                    FilterType::Keyword => text.contains(&self.filter.text),
                    FilterType::Regex => match regex::Regex::new(&self.filter.text) {
                        Ok(re) => re.is_match(text),
                        Err(_) => true,
                    },
                    FilterType::None => true,
                };
                if !ok {
                    continue;
                }
            }
            out.push(idx);
        }
        out
    }

    fn summary_for(&mut self, idx: usize) -> crate::textgen::Summary {
        if let Some(s) = self.summaries.get(&idx) {
            return *s;
        }
        let before_text = if idx > 0 {
            self.history[idx - 1].selected(self.cfg.output_mode).to_string()
        } else {
            String::new()
        };
        let after_text = self.history[idx].selected(self.cfg.output_mode).to_string();
        let s = summary_counts(&before_text, &after_text, self.cfg.enable_summary_char);
        self.summaries.insert(idx, s);
        s
    }

    fn watch_text(&self) -> Text<'static> {
        let (after, before) = self.selected_result();
        let opt = TextOptions {
            diff_mode: self.cfg.diff_mode,
            diff_only: self.cfg.diff_output_only,
            line_number: self.cfg.line_number,
            reverse: self.cfg.reverse,
            output_mode: self.cfg.output_mode,
            ansi: self.cfg.color,
        };
        let text = create_text(&after, &before, &opt);
        let text = self.expand_tabs(text);
        let text = if self.cfg.color { text } else { escape_esc(text) };
        let text = self.apply_keyword_highlight(text);
        text
    }

    fn expand_tabs(&self, text: Text<'static>) -> Text<'static> {
        let tab = self.cfg.tab_size as usize;
        let mut lines: Vec<Line<'static>> = Vec::new();
        for line in text.lines {
            let alignment = line.alignment;
            // Flatten to (char, style)
            let mut chars: Vec<(char, Style)> = Vec::new();
            for span in &line.spans {
                for ch in span.content.chars() {
                    chars.push((ch, span.style));
                }
            }
            let mut out: Vec<(char, Style)> = Vec::new();
            let mut col = 0usize;
            for (ch, st) in chars {
                if ch == '\t' {
                    if tab == 0 {
                        continue;
                    }
                    let n = tab - (col % tab);
                    for _ in 0..n {
                        out.push((' ', st));
                        col += 1;
                    }
                } else {
                    col += UnicodeWidthChar::width(ch).unwrap_or(0);
                    out.push((ch, st));
                }
            }
            lines.push(chars_to_line(out, alignment));
        }
        Text::from(lines)
    }

    fn apply_keyword_highlight(&self, text: Text<'static>) -> Text<'static> {
        if !self.filter.active() {
            return text;
        }
        let re: Option<regex::Regex> = match self.filter.typ {
            FilterType::Regex => regex::Regex::new(&self.filter.text).ok(),
            _ => None,
        };
        if self.filter.typ == FilterType::Regex && re.is_none() {
            return text;
        }
        let hl = Style::default().fg(Color::Black).bg(Color::Yellow);
        let mut lines: Vec<Line<'static>> = Vec::new();
        for line in text.lines {
            let alignment = line.alignment;
            let mut chars: Vec<(char, Style)> = Vec::new();
            for span in &line.spans {
                for ch in span.content.chars() {
                    chars.push((ch, span.style));
                }
            }
            let s: String = chars.iter().map(|c| c.0).collect();
            // Compute highlighted char ranges (byte ranges converted).
            let mut hl_flags = vec![false; chars.len()];
            let matches: Vec<(usize, usize)> = match self.filter.typ {
                FilterType::Keyword => {
                    let mut v = Vec::new();
                    if !self.filter.text.is_empty() {
                        let mut start = 0usize;
                        while let Some(pos) = s[start..].find(&self.filter.text) {
                            let a = start + pos;
                            v.push((a, a + self.filter.text.len()));
                            start = a + self.filter.text.len();
                            if start >= s.len() { break; }
                        }
                    }
                    v
                }
                FilterType::Regex => re
                    .as_ref()
                    .map(|r| r.find_iter(&s).map(|m| (m.start(), m.end())).collect())
                    .unwrap_or_default(),
                FilterType::None => Vec::new(),
            };
            // Map byte offsets to char indices.
            let mut byte_to_char: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();
            for (ci, (bi, _)) in s.char_indices().enumerate() {
                byte_to_char.insert(bi, ci);
            }
            byte_to_char.insert(s.len(), chars.len());
            for (a, b) in matches {
                if let (Some(&ca), Some(&cb)) = (byte_to_char.get(&a), byte_to_char.get(&b)) {
                    for f in hl_flags.iter_mut().take(cb).skip(ca) {
                        *f = true;
                    }
                }
            }
            let out: Vec<(char, Style)> = chars
                .into_iter()
                .enumerate()
                .map(|(i, (ch, st))| (ch, if hl_flags[i] { hl } else { st }))
                .collect();
            lines.push(chars_to_line(out, alignment));
        }
        Text::from(lines)
    }

    // ---------------- drawing ----------------

    fn draw(&mut self, frame: &mut Frame) {
        let size = frame.area();
        self.last_frame_size = size;
        if self.header_dirty {
            self.header_width = size.width;
            self.header_dirty = false;
        }
        let show_header = self.show_title;
        let header_h: u16 = if show_header { 2 } else { 0 };
        let border_top_h: u16 = if show_header && self.cfg.border { 1 } else { 0 };
        let body_y = header_h + border_top_h;
        let body_h = size.height.saturating_sub(body_y);
        let history_visible = self.show_history && self.show_title || (self.show_history && !self.show_title && self.history_toggled_after_title());
        // NOTE: `t` hides both header and history; BSpace toggles history independently.
        let history_visible = self.effective_history_visible();
        let _ = history_visible;

        if show_header {
            let header_area = Rect::new(0, 0, size.width, 2.min(size.height));
            frame.render_widget(Paragraph::new(self.header_text()), header_area);
            if self.cfg.border && size.height > 2 {
                let y = 2;
                let watch_w = self.watch_width(size.width);
                let mut line = String::new();
                for x in 0..size.width {
                    if self.effective_history_visible() && watch_w > 0 && x == watch_w - 1 {
                        line.push('┬');
                    } else {
                        line.push('─');
                    }
                }
                frame.render_widget(
                    Paragraph::new(Line::from(Span::styled(line, Style::default().fg(Color::Gray)))),
                    Rect::new(0, y, size.width, 1),
                );
            }
        }

        let watch_w = self.watch_width(size.width);
        let hist_w = size.width.saturating_sub(watch_w);
        let watch_area_full = Rect::new(0, body_y, watch_w, body_h);
        let hist_area = Rect::new(watch_w, body_y, hist_w, body_h);
        self.last_history_area = hist_area;

        // Watch pane: with border, the right column is the divider/scrollbar.
        let watch_inner_w = if self.cfg.border {
            watch_w.saturating_sub(1)
        } else {
            watch_w
        };
        let watch_area = Rect::new(0, body_y, watch_inner_w, body_h);
        self.last_watch_area = Rect::new(0, body_y.saturating_sub(border_top_h), watch_w, body_h + border_top_h);

        if watch_area.width > 0 && watch_area.height > 0 {
            let text = self.watch_text();
            // Clamp scroll.
            let max_y = self.max_watch_scroll_y(&text, watch_area.width, watch_area.height);
            if self.watch_scroll_y > max_y {
                self.watch_scroll_y = max_y;
            }
            let max_x = self.max_watch_scroll_x(&text, watch_area.width);
            if self.watch_scroll_x > max_x {
                self.watch_scroll_x = max_x;
            }
            let mut p = Paragraph::new(text.clone())
                .scroll((self.watch_scroll_y as u16, self.watch_scroll_x as u16));
            if self.wrap {
                p = p.wrap(Wrap { trim: false });
            }
            frame.render_widget(p, watch_area);
            if self.cfg.border && watch_w > 0 {
                let divider_x = watch_w - 1;
                if self.cfg.with_scrollbar {
                    let total = self.watch_display_line_count(&text, watch_area.width);
                    let mut state = ScrollbarState::new(total)
                        .viewport_content_length(watch_area.height as usize)
                        .position(self.watch_scroll_y);
                    let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight)
                        .begin_symbol(None)
                        .end_symbol(None)
                        .track_symbol(Some("│"))
                        .thumb_symbol("█");
                    frame.render_stateful_widget(
                        sb,
                        Rect::new(divider_x, body_y, 1, body_h),
                        &mut state,
                    );
                } else {
                    let s: String = std::iter::repeat_n("│\n", body_h as usize).collect();
                    frame.render_widget(
                        Paragraph::new(s.trim_end_matches('\n').to_string()),
                        Rect::new(divider_x, body_y, 1, body_h),
                    );
                }
            }
            let _ = watch_area_full;
        }

        if self.effective_history_visible() && hist_area.width > 0 && hist_area.height > 0 {
            let hist_text = self.history_text();
            // Adjust scroll to keep the selected line visible.
            let sel_line = self.selected_history_line();
            let h = hist_area.height as usize;
            if h > 0 {
                if sel_line < self.history_scroll_y {
                    self.history_scroll_y = sel_line;
                } else if sel_line >= self.history_scroll_y + h {
                    self.history_scroll_y = sel_line + 1 - h;
                }
            }
            let p = Paragraph::new(hist_text).scroll((self.history_scroll_y as u16, 0));
            frame.render_widget(p, hist_area);
        }

        match self.popup {
            Popup::Help => self.draw_help(frame),
            Popup::Exit => self.draw_exit(frame),
            Popup::None => {}
        }
    }

    fn history_toggled_after_title(&self) -> bool {
        false
    }

    fn effective_history_visible(&self) -> bool {
        self.show_history && self.show_title_visible_for_history()
    }

    fn show_title_visible_for_history(&self) -> bool {
        // `t` toggles a single flag that controls both header and history.
        // We model that with show_title itself for the common case, but
        // BSpace can re-show history while the header stays hidden: that is
        // tracked by setting show_history=true while show_title=false and
        // remembering it in history_forced.
        self.show_title || self.history_forced()
    }

    fn history_forced(&self) -> bool {
        self.history_forced_flag
    }

    fn watch_width(&self, total: u16) -> u16 {
        if self.effective_history_visible() {
            total.saturating_sub(25)
        } else {
            total
        }
    }

    fn header_text(&self) -> Text<'static> {
        let latest = self.latest.clone().unwrap_or_default();
        let interval_text = if *self.paused_shared.lock().unwrap() {
            format!("{:>9}", "Paused")
        } else {
            format!("{:>9.3}", self.cfg.interval)
        };
        let w = self.header_width as usize;
        let cmd_width = if self.cfg.no_help_banner {
            w.saturating_sub(41)
        } else {
            w.saturating_sub(66)
        };
        let cmd_field = format!("{:<width$}", latest.command, width = cmd_width);
        let cmd_color = if latest.status { Color::Green } else { Color::Red };
        let mut line1: Vec<Span<'static>> = vec![
            Span::raw("Every "),
            Span::styled(interval_text, Style::default().fg(Color::Cyan)),
            Span::raw(":"),
            Span::styled(cmd_field, Style::default().fg(cmd_color)),
            Span::raw(" "),
        ];
        if !self.cfg.no_help_banner {
            line1.push(Span::styled(
                "Display help with h key!".to_string(),
                Style::default().add_modifier(Modifier::REVERSED),
            ));
            line1.push(Span::raw(" "));
        }
        line1.push(Span::styled(latest.timestamp.clone(), Style::default().fg(Color::Cyan)));

        // Second line: filter field + boxes.
        let boxes = self.header_boxes();
        let boxes_len = 58usize;
        let field_w = (self.header_width as usize).saturating_sub(boxes_len + 1);
        let mut line2: Vec<Span<'static>> = Vec::new();
        if self.filter.typ != FilterType::None || self.filter.editing {
            let mark = if self.filter.editing && !self.filter.text.is_empty() {
                ' '
            } else {
                match self.filter.typ {
                    FilterType::Keyword => '/',
                    FilterType::Regex => '*',
                    FilterType::None => ' ',
                }
            };
            let shown = if self.filter.editing { &self.filter.input } else { &self.filter.text };
            line2.push(Span::styled(mark.to_string(), Style::default().fg(Color::Gray)));
            let text_w = field_w.saturating_sub(1);
            let padded = format!("{:<width$}", shown, width = text_w);
            line2.push(Span::styled(
                padded,
                Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
            ));
        } else if field_w > 0 {
            line2.push(Span::styled(" ".repeat(field_w), Style::default().fg(Color::Gray)));
        }
        line2.extend(boxes);
        Text::from(vec![Line::from(line1), Line::from(line2)])
    }

    fn header_boxes(&self) -> Vec<Span<'static>> {
        let on = Style::default().fg(Color::Green).add_modifier(Modifier::BOLD | Modifier::REVERSED);
        let off = Style::default();
        let mut v: Vec<Span<'static>> = Vec::new();
        let mut bx = |label: &str, style: Style, v: &mut Vec<Span<'static>>| {
            v.push(Span::raw("["));
            v.push(Span::styled(label.to_string(), style));
            v.push(Span::raw("] "));
        };
        bx("Number", if self.cfg.line_number { on } else { off }, &mut v);
        bx("Color", if self.cfg.color { on } else { off }, &mut v);
        bx("Reverse", if self.cfg.reverse { on } else { off }, &mut v);
        bx(
            self.cfg.output_mode.label(),
            Style::default().fg(Color::Yellow).add_modifier(Modifier::REVERSED),
            &mut v,
        );
        let focus_label = match self.focus {
            Focus::History => "History".to_string(),
            Focus::Watch => format!("{:<7}", "Watch"),
        };
        bx(
            &focus_label,
            Style::default().fg(Color::Cyan).add_modifier(Modifier::REVERSED),
            &mut v,
        );
        let diff_label = {
            let base = self.cfg.diff_mode.label();
            let s = if self.cfg.diff_output_only
                && matches!(self.cfg.diff_mode, DiffMode::Line | DiffMode::Word)
            {
                format!("{}(Only)", base)
            } else {
                base.to_string()
            };
            format!("{:<10}", s)
        };
        v.push(Span::raw("["));
        v.push(Span::styled(
            diff_label,
            Style::default().fg(Color::Magenta).add_modifier(Modifier::REVERSED),
        ));
        v.push(Span::raw("]"));
        v
    }

    fn history_lines(&mut self) -> Vec<Line<'static>> {
        let mut lines: Vec<Line<'static>> = Vec::new();
        let sel = self.selection;
        let focus_bg = if self.focus == Focus::History { Color::Blue } else { Color::DarkGray };
        // Virtual latest line.
        if sel.is_none() {
            lines.push(Line::from(Span::styled(
                ">>latest".to_string(),
                Style::default().fg(Color::Gray).bg(focus_bg).add_modifier(Modifier::BOLD),
            )));
        } else {
            lines.push(Line::from(Span::raw("  latest".to_string())));
        }
        let idxs = self.displayed_indices();
        // Summaries must be computed before borrowing history immutably below.
        let mut summaries: std::collections::HashMap<usize, crate::textgen::Summary> = std::collections::HashMap::new();
        if self.show_summary {
            for &hi in &idxs {
                summaries.insert(hi, self.summary_for(hi));
            }
        }
        for (pos, &hi) in idxs.iter().enumerate() {
            let entry = &self.history[hi];
            if sel == Some(pos) {
                lines.push(Line::from(Span::styled(
                    format!(">>{}", entry.timestamp),
                    Style::default().fg(Color::Gray).bg(focus_bg).add_modifier(Modifier::BOLD),
                )));
            } else {
                let color = if entry.status { Color::Green } else { Color::Red };
                lines.push(Line::from(vec![
                    Span::raw("  ".to_string()),
                    Span::styled(entry.timestamp.clone(), Style::default().fg(color)),
                ]));
            }
            if self.show_summary {
                if let Some(s) = summaries.get(&hi) {
                    lines.push(Line::from(vec![
                        Span::raw(" Line: ".to_string()),
                        Span::styled(format!("+{:>7}", s.line_plus), Style::default().fg(Color::Green)),
                        Span::raw(" ".to_string()),
                        Span::styled(format!("-{:>7}", s.line_minus), Style::default().fg(Color::Red)),
                    ]));
                    if self.cfg.enable_summary_char {
                        lines.push(Line::from(vec![
                            Span::raw(" Char: ".to_string()),
                            Span::styled(format!("+{:>7}", s.char_plus), Style::default().fg(Color::Green)),
                            Span::raw(" ".to_string()),
                            Span::styled(format!("-{:>7}", s.char_minus), Style::default().fg(Color::Red)),
                        ]));
                    }
                }
            }
        }
        lines
    }

    fn history_text(&mut self) -> Text<'static> {
        Text::from(self.history_lines())
    }

    fn selected_history_line(&self) -> usize {
        match self.selection {
            None => 0,
            Some(pos) => {
                let mut line = 1usize;
                let per = if self.show_summary {
                    1 + if self.cfg.enable_summary_char { 2 } else { 1 }
                } else {
                    1
                };
                line += pos * per;
                line
            }
        }
    }

    fn watch_display_line_count(&self, text: &Text<'_>, width: u16) -> usize {
        if width == 0 {
            return text.lines.len();
        }
        if !self.wrap {
            return text.lines.len();
        }
        let mut count = 0usize;
        for line in &text.lines {
            let w: usize = line
                .spans
                .iter()
                .map(|s| s.content.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum::<usize>())
                .sum();
            if w == 0 {
                count += 1;
            } else {
                count += (w + width as usize - 1) / width as usize;
            }
        }
        count
    }

    fn max_watch_scroll_y(&self, text: &Text<'_>, width: u16, height: u16) -> usize {
        let total = self.watch_display_line_count(text, width);
        total.saturating_sub(height as usize + 1)
    }
    fn max_watch_scroll_x(&self, text: &Text<'_>, width: u16) -> usize {
        if self.wrap {
            return 0;
        }
        let maxw = text
            .lines
            .iter()
            .map(|l| {
                l.spans
                    .iter()
                    .map(|s| s.content.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum::<usize>())
                    .sum::<usize>()
            })
            .max()
            .unwrap_or(0);
        maxw.saturating_sub(width as usize)
    }

    fn popup_rect(&self, percent_x: u16, percent_y: u16, area: Rect) -> Rect {
        let v = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Percentage((100 - percent_y) / 2),
                Constraint::Percentage(percent_y),
                Constraint::Percentage((100 - percent_y) / 2),
            ])
            .split(area);
        let h = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Percentage((100 - percent_x) / 2),
                Constraint::Percentage(percent_x),
                Constraint::Percentage((100 - percent_x) / 2),
            ])
            .split(v[1]);
        h[1]
    }

    fn draw_help(&mut self, frame: &mut Frame) {
        let area = self.popup_rect(80, 70, frame.area());
        let mut lines: Vec<Line<'static>> = Vec::new();
        let base = Style::default().fg(Color::LightGreen);
        for &action in Action::all_in_order() {
            for (k, a) in self.cfg.keymap.iter() {
                if *a == action {
                    lines.push(Line::from(vec![
                        Span::styled(" - [".to_string(), base),
                        Span::styled(format!("{}", k), Style::default().fg(Color::Yellow)),
                        Span::styled("] key :".to_string(), base),
                    ]));
                    lines.push(Line::from(vec![
                        Span::styled("         ".to_string(), base),
                        Span::styled(
                            action.description().to_string(),
                            Style::default().fg(Color::White),
                        ),
                    ]));
                }
            }
        }
        lines.push(Line::from(""));
        lines.push(Line::from(""));
        let inner_h = area.height.saturating_sub(2);
        self.last_help_inner_h = inner_h;
        let max_scroll = (lines.len()).saturating_sub(inner_h as usize);
        if self.help_scroll > max_scroll {
            self.help_scroll = max_scroll;
        }
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Plain)
            .border_style(Style::default().fg(Color::Gray))
            .title(" [help] ");
        let p = Paragraph::new(Text::from(lines))
            .style(base)
            .block(block)
            .scroll((self.help_scroll as u16, 0));
        frame.render_widget(Clear, area);
        frame.render_widget(p, area);
    }

    fn draw_exit(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let w = 32u16.min(area.width);
        let h = 5u16.min(area.height);
        let x = area.x + area.width.saturating_sub(w) / 2;
        let y = area.y + area.height.saturating_sub(h) / 2;
        let rect = Rect::new(x, y, w, h);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Double)
            .border_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))
            .title(" [exit] ");
        let text = Text::from(vec![
            Line::from(" Exit hwatch?"),
            Line::from("   Press 'Y' or 'Q'  : Quit."),
            Line::from("   Press 'N' or 'Esc': Stay."),
        ]);
        let p = Paragraph::new(text).block(block);
        frame.render_widget(Clear, rect);
        frame.render_widget(p, rect);
    }

    // ---------------- events ----------------

    fn handle_event(&mut self, ev: Event) {
        match ev {
            Event::Key(key) => self.handle_key(key),
            Event::Mouse(me) => self.handle_mouse(me.kind, me.column, me.row),
            Event::Resize(_, _) => {
                self.header_dirty = true;
            }
            _ => {}
        }
    }

    fn handle_mouse(&mut self, kind: MouseEventKind, col: u16, row: u16) {
        let key = match kind {
            MouseEventKind::ScrollUp => Key::new(KeyKind::MouseScrollUp),
            MouseEventKind::ScrollDown => Key::new(KeyKind::MouseScrollDown),
            MouseEventKind::ScrollLeft => Key::new(KeyKind::MouseScrollLeft),
            MouseEventKind::ScrollRight => Key::new(KeyKind::MouseScrollRight),
            MouseEventKind::Down(MouseButton::Left) => Key::new(KeyKind::MouseButtonDownLeft),
            MouseEventKind::Down(MouseButton::Right) => Key::new(KeyKind::MouseButtonDownRight),
            MouseEventKind::Up(MouseButton::Left) => Key::new(KeyKind::MouseButtonUpLeft),
            MouseEventKind::Up(MouseButton::Right) => Key::new(KeyKind::MouseButtonUpRight),
            _ => return,
        };
        if let Some(&action) = self.cfg.keymap.get(&key) {
            self.do_action(action, Some((col, row)));
        }
    }

    fn handle_key(&mut self, key: KeyEvent) {
        if key.kind == event::KeyEventKind::Release {
            return;
        }
        // Filter editing takes most keys.
        if self.filter.editing {
            match key.code {
                KeyCode::Enter => {
                    self.filter.text = self.filter.input.clone();
                    self.filter.editing = false;
                    self.selection = None;
                    self.focus_first_keyword();
                    self.header_dirty = true;
                    return;
                }
                KeyCode::Backspace => {
                    self.filter.input.pop();
                    self.header_dirty = true;
                    return;
                }
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    // Only the Cancel action bound to Ctrl-C matters here.
                    if let Some(k) = key_from_event(&key) {
                        if self.cfg.keymap.get(&k) == Some(&Action::Cancel) {
                            self.filter.editing = false;
                            self.filter.input = self.filter.text.clone();
                            self.header_dirty = true;
                            return;
                        }
                    }
                }
                KeyCode::Char(c) => {
                    if !c.is_control() {
                        self.filter.input.push(c);
                        self.header_dirty = true;
                    }
                    return;
                }
                _ => return,
            }
        }
        // Raw exit-confirmation keys.
        if self.popup == Popup::Exit {
            if let KeyCode::Char(c) = key.code {
                if !key.modifiers.contains(KeyModifiers::CONTROL) {
                    match c {
                        'y' | 'q' => {
                            self.should_quit = true;
                            return;
                        }
                        'n' => {
                            self.popup = Popup::None;
                            return;
                        }
                        _ => {}
                    }
                }
            }
        }
        if let Some(k) = key_from_event(&key) {
            if let Some(&action) = self.cfg.keymap.get(&k) {
                self.do_action(action, None);
            }
        }
    }

    fn focus_first_keyword(&mut self) {
        self.filter.focus_line = None;
        self.move_keyword(true, true);
    }

    fn keyword_match_lines(&self) -> Vec<usize> {
        if !self.filter.active() {
            return Vec::new();
        }
        let text = self.watch_text();
        let re: Option<regex::Regex> = match self.filter.typ {
            FilterType::Regex => regex::Regex::new(&self.filter.text).ok(),
            _ => None,
        };
        let mut out = Vec::new();
        for (i, line) in text.lines.iter().enumerate() {
            let s: String = line.spans.iter().map(|s| s.content.as_ref()).collect();
            let hit = match self.filter.typ {
                FilterType::Keyword => s.contains(&self.filter.text),
                FilterType::Regex => re.as_ref().map(|r| r.is_match(&s)).unwrap_or(false),
                FilterType::None => false,
            };
            if hit {
                out.push(i);
            }
        }
        out
    }

    fn move_keyword(&mut self, forward: bool, first: bool) {
        let matches = self.keyword_match_lines();
        if matches.is_empty() {
            self.filter.focus_line = None;
            return;
        }
        let next = if first {
            if forward { matches[0] } else { matches[matches.len() - 1] }
        } else {
            match self.filter.focus_line {
                None => {
                    if forward { matches[0] } else { matches[matches.len() - 1] }
                }
                Some(cur) => {
                    if forward {
                        matches.iter().find(|&&m| m > cur).copied().unwrap_or(matches[0])
                    } else {
                        matches.iter().rev().find(|&&m| m < cur).copied().unwrap_or(matches[matches.len() - 1])
                    }
                }
            }
        };
        self.filter.focus_line = Some(next);
        // Reveal it.
        let h = self.last_watch_area.height as usize;
        if h > 0 {
            if next < self.watch_scroll_y {
                self.watch_scroll_y = next;
            } else if next >= self.watch_scroll_y + h {
                self.watch_scroll_y = next + 1 - h;
            }
        }
    }

    fn do_action(&mut self, action: Action, mouse: Option<(u16, u16)>) {
        use Action as A;
        // Help popup consumes scroll keys for itself.
        if self.popup == Popup::Help {
            match action {
                A::Up => {
                    self.help_scroll = self.help_scroll.saturating_sub(1);
                    return;
                }
                A::Down => {
                    self.help_scroll += 1;
                    return;
                }
                A::PageUp => {
                    let amt = self.page_amount(self.last_help_inner_h as usize);
                    self.help_scroll = self.help_scroll.saturating_sub(amt);
                    return;
                }
                A::PageDown => {
                    let amt = self.page_amount(self.last_help_inner_h as usize);
                    self.help_scroll += amt;
                    return;
                }
                A::MoveTop => {
                    self.help_scroll = 0;
                    return;
                }
                A::MoveEnd => {
                    self.help_scroll = usize::MAX / 2;
                    return;
                }
                _ => {}
            }
        }
        match action {
            A::None => {}
            A::Quit => {
                if self.popup == Popup::Exit {
                    self.should_quit = true;
                } else {
                    self.popup = Popup::Exit;
                }
            }
            A::Cancel => {
                if self.popup == Popup::Help {
                    self.popup = Popup::None;
                } else if self.popup == Popup::Exit {
                    self.should_quit = true;
                } else if self.filter.typ != FilterType::None {
                    self.filter.reset();
                    self.selection = None;
                    self.header_dirty = true;
                } else {
                    self.popup = Popup::Exit;
                }
            }
            A::Reset => {
                if self.popup == Popup::Exit {
                    self.popup = Popup::None;
                } else if self.filter.typ != FilterType::None {
                    self.filter.reset();
                    self.selection = None;
                    self.header_dirty = true;
                } else if self.popup != Popup::Help {
                    self.popup = Popup::Exit;
                }
            }
            A::Help => {
                if self.popup == Popup::Help {
                    self.popup = Popup::None;
                } else {
                    self.popup = Popup::Help;
                    self.help_scroll = 0;
                }
            }
            A::Up => self.move_focus(-1, mouse),
            A::Down => self.move_focus(1, mouse),
            A::PageUp => self.move_focus_page(false, mouse),
            A::PageDown => self.move_focus_page(true, mouse),
            A::MoveTop => self.move_focus_home(mouse),
            A::MoveEnd => self.move_focus_end(mouse),
            A::ScrollLeft => {
                self.watch_scroll_x = self.watch_scroll_x.saturating_sub(1);
            }
            A::ScrollRight => {
                self.watch_scroll_x += 1;
            }
            A::ScrollHorizontalHome => {
                self.watch_scroll_x = 0;
            }
            A::ScrollHorizontalEnd => {
                let text = self.watch_text();
                self.watch_scroll_x = self.max_watch_scroll_x(&text, self.last_watch_area.width);
            }
            A::ToggleForcus => {
                self.focus = match self.focus {
                    Focus::History => Focus::Watch,
                    Focus::Watch => Focus::History,
                };
                self.header_dirty = true;
            }
            A::ForcusWatchPane => {
                self.focus = Focus::Watch;
                self.header_dirty = true;
            }
            A::ForcusHistoryPane => {
                self.focus = Focus::History;
                self.header_dirty = true;
            }
            A::ToggleColor => {
                self.cfg.color = !self.cfg.color;
                self.header_dirty = true;
            }
            A::ToggleLineNumber => {
                self.cfg.line_number = !self.cfg.line_number;
                self.header_dirty = true;
            }
            A::ToggleReverse => {
                self.cfg.reverse = !self.cfg.reverse;
                self.header_dirty = true;
            }
            A::ToggleMouseSupport => {
                self.cfg.mouse = !self.cfg.mouse;
                // Mouse capture is toggled in the draw loop via a marker:
                // reuse pending state through stdout directly.
                let mut so = stdout();
                if self.cfg.mouse {
                    let _ = execute!(so, crossterm::event::EnableMouseCapture);
                } else {
                    let _ = execute!(so, crossterm::event::DisableMouseCapture);
                }
            }
            A::ToggleViewHeaderPane => {
                self.show_title = !self.show_title;
                self.header_dirty = true;
            }
            A::ToggleViewHistoryPane => {
                if self.show_title {
                    self.show_history = !self.show_history;
                } else {
                    self.history_forced_flag = !self.history_forced_flag;
                    self.show_history = true;
                }
            }
            A::ToggleBorder => {
                self.cfg.border = !self.cfg.border;
                self.cfg.with_scrollbar = !self.cfg.with_scrollbar;
            }
            A::ToggleDiffMode => {
                self.cfg.diff_mode = self.cfg.diff_mode.next();
                self.header_dirty = true;
            }
            A::SetDiffModePlane => {
                self.cfg.diff_mode = DiffMode::None;
                self.header_dirty = true;
            }
            A::SetDiffModeWatch => {
                self.cfg.diff_mode = DiffMode::Watch;
                self.header_dirty = true;
            }
            A::SetDiffModeLine => {
                self.cfg.diff_mode = DiffMode::Line;
                self.header_dirty = true;
            }
            A::SetDiffModeWord => {
                self.cfg.diff_mode = DiffMode::Word;
                self.header_dirty = true;
            }
            A::SetDiffOnly => {
                self.cfg.diff_output_only = !self.cfg.diff_output_only;
                self.header_dirty = true;
            }
            A::ToggleOutputMode => {
                self.cfg.output_mode = self.cfg.output_mode.next();
                self.selection = None;
                self.summaries.clear();
                self.header_dirty = true;
            }
            A::SetOutputModeOutput => {
                self.cfg.output_mode = OutputMode::Output;
                self.selection = None;
                self.summaries.clear();
                self.header_dirty = true;
            }
            A::SetOutputModeStdout => {
                self.cfg.output_mode = OutputMode::Stdout;
                self.selection = None;
                self.summaries.clear();
                self.header_dirty = true;
            }
            A::SetOutputModeStderr => {
                self.cfg.output_mode = OutputMode::Stderr;
                self.selection = None;
                self.summaries.clear();
                self.header_dirty = true;
            }
            A::ToggleWrapMode => {
                self.wrap = !self.wrap;
                if self.wrap {
                    self.watch_scroll_x = 0;
                }
            }
            A::NextKeyword => self.move_keyword(true, false),
            A::PrevKeyword => self.move_keyword(false, false),
            A::ToggleHistorySummary => {
                self.show_summary = !self.show_summary;
            }
            A::IntervalPlus => {
                self.cfg.interval += 0.5;
                *self.interval_shared.lock().unwrap() = self.cfg.interval;
                self.header_dirty = true;
            }
            A::IntervalMinus => {
                self.cfg.interval -= 0.5;
                if self.cfg.interval < 0.0 {
                    // Reference clamps only in the sense that it cannot go
                    // below 0.0 from key presses ("as long as it's positive").
                    // Keep the raw value consistent with that behaviour.
                    self.cfg.interval = 0.0;
                }
                *self.interval_shared.lock().unwrap() = self.cfg.interval;
                self.header_dirty = true;
            }
            A::TogglePause => {
                let mut p = self.paused_shared.lock().unwrap();
                *p = !*p;
                drop(p);
                self.header_dirty = true;
            }
            A::ChangeFilterMode => {
                self.filter.typ = FilterType::Keyword;
                self.filter.input = self.filter.text.clone();
                self.filter.editing = true;
                self.header_dirty = true;
            }
            A::ChangeRegexFilterMode => {
                self.filter.typ = FilterType::Regex;
                self.filter.input = self.filter.text.clone();
                self.filter.editing = true;
                self.header_dirty = true;
            }
            A::MouseScrollUp => self.mouse_scroll(mouse, -1),
            A::MouseScrollDown => self.mouse_scroll(mouse, 1),
            A::MouseButtonLeft => self.mouse_click(mouse),
        }
    }

    fn page_amount(&self, area_h: usize) -> usize {
        // Page movement is based on the full frame height.
        let h = self.last_frame_size.height as usize;
        if h > 3 { h - 3 } else if area_h > 1 { area_h - 1 } else { 1 }
    }

    fn focus_for_mouse(&self, mouse: Option<(u16, u16)>) -> Focus {
        if let Some((col, _row)) = mouse {
            if self.effective_history_visible() && col >= self.last_history_area.x {
                return Focus::History;
            }
            return Focus::Watch;
        }
        self.focus
    }

    fn move_focus(&mut self, delta: i64, mouse: Option<(u16, u16)>) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => {
                if delta > 0 {
                    self.watch_scroll_y += delta as usize;
                } else {
                    self.watch_scroll_y = self.watch_scroll_y.saturating_sub((-delta) as usize);
                }
            }
            Focus::History => {
                self.move_selection(delta);
            }
        }
    }
    fn move_focus_page(&mut self, down: bool, mouse: Option<(u16, u16)>) {
        let amt = self.page_amount(0) as i64;
        self.move_focus(if down { amt } else { -amt }, mouse);
    }
    fn move_focus_home(&mut self, mouse: Option<(u16, u16)>) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => self.watch_scroll_y = 0,
            Focus::History => {
                self.selection = None;
                self.watch_scroll_y = 0;
                self.watch_scroll_x = 0;
            }
        }
    }
    fn move_focus_end(&mut self, mouse: Option<(u16, u16)>) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => {
                self.watch_scroll_y = usize::MAX / 2;
            }
            Focus::History => {
                let n = self.displayed_indices().len();
                if n > 0 {
                    self.set_selection_pos(n - 1);
                }
            }
        }
    }

    fn set_selection_pos(&mut self, pos: usize) {
        self.selection = Some(pos);
        self.watch_scroll_y = 0;
        self.watch_scroll_x = 0;
    }

    fn move_selection(&mut self, delta: i64) {
        let n = self.displayed_indices().len();
        // Positions: -1 = latest (None), 0..n-1 = displayed entries.
        let cur: i64 = match self.selection {
            None => -1,
            Some(p) => p as i64,
        };
        let mut next = cur + delta;
        if next < -1 {
            next = -1;
        }
        if next > n as i64 - 1 {
            next = n as i64 - 1;
        }
        if next == cur {
            return;
        }
        if next < 0 {
            self.selection = None;
            self.watch_scroll_y = 0;
            self.watch_scroll_x = 0;
        } else {
            self.set_selection_pos(next as usize);
        }
    }

    fn mouse_scroll(&mut self, mouse: Option<(u16, u16)>, dir: i64) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => {
                if dir > 0 {
                    self.watch_scroll_y += 2;
                } else {
                    self.watch_scroll_y = self.watch_scroll_y.saturating_sub(2);
                }
            }
            Focus::History => {
                self.move_selection(dir);
            }
        }
    }

    fn mouse_click(&mut self, mouse: Option<(u16, u16)>) {
        if let Some((col, row)) = mouse {
            if self.effective_history_visible()
                && col >= self.last_history_area.x
                && col < self.last_history_area.x + self.last_history_area.width
                && row >= self.last_history_area.y
                && row < self.last_history_area.y + self.last_history_area.height
            {
                let line = self.history_scroll_y + (row - self.last_history_area.y) as usize;
                if line == 0 {
                    self.selection = None;
                    self.watch_scroll_y = 0;
                    self.watch_scroll_x = 0;
                    return;
                }
                let per = if self.show_summary {
                    1 + if self.cfg.enable_summary_char { 2 } else { 1 }
                } else {
                    1
                };
                let pos = (line - 1) / per;
                if pos < self.displayed_indices().len() {
                    self.set_selection_pos(pos);
                }
            }
        }
    }
}

fn chars_to_line(chars: Vec<(char, Style)>, alignment: Option<ratatui::layout::Alignment>) -> Line<'static> {
    let mut spans: Vec<Span<'static>> = Vec::new();
    for (ch, st) in chars {
        if let Some(last) = spans.last_mut() {
            let last: &mut Span<'static> = last;
            if last.style == st {
                last.content.to_mut().push(ch);
                continue;
            }
        }
        spans.push(Span::styled(ch.to_string(), st));
    }
    if spans.is_empty() {
        spans.push(Span::raw(""));
    }
    let mut line = Line::from(spans);
    line.alignment = alignment;
    line
}

fn escape_esc(text: Text<'static>) -> Text<'static> {
    let mut lines = Vec::new();
    for line in text.lines {
        let alignment = line.alignment;
        let mut spans = Vec::new();
        for span in line.spans {
            if span.content.contains('\x1b') {
                spans.push(Span::styled(
                    span.content.replace('\x1b', "\\x1b"),
                    span.style,
                ));
            } else {
                spans.push(span);
            }
        }
        let mut l = Line::from(spans);
        l.alignment = alignment;
        lines.push(l);
    }
    Text::from(lines)
}

fn key_from_event(ev: &KeyEvent) -> Option<Key> {
    let mods = ev.modifiers;
    let ctrl = mods.contains(KeyModifiers::CONTROL);
    let alt = mods.contains(KeyModifiers::ALT);
    let meta = mods.contains(KeyModifiers::META) || mods.contains(KeyModifiers::SUPER);
    let mut shift = mods.contains(KeyModifiers::SHIFT);
    let kind = match ev.code {
        KeyCode::Char(c) => {
            let mut ch = c;
            if c.is_ascii_uppercase() {
                ch = c.to_ascii_lowercase();
                shift = true;
            }
            KeyKind::Char(ch)
        }
        KeyCode::Up => KeyKind::Up,
        KeyCode::Down => KeyKind::Down,
        KeyCode::Left => KeyKind::Left,
        KeyCode::Right => KeyKind::Right,
        KeyCode::Home => KeyKind::Home,
        KeyCode::End => KeyKind::End,
        KeyCode::PageUp => KeyKind::PageUp,
        KeyCode::PageDown => KeyKind::PageDown,
        KeyCode::Backspace => KeyKind::Backspace,
        KeyCode::Delete => KeyKind::Delete,
        KeyCode::Insert => KeyKind::Insert,
        KeyCode::Tab => KeyKind::Tab,
        KeyCode::BackTab => {
            shift = true;
            KeyKind::Tab
        }
        KeyCode::Enter => KeyKind::Enter,
        KeyCode::Esc => KeyKind::Esc,
        KeyCode::F(n) => KeyKind::F(n),
        _ => return None,
    };
    Some(Key { ctrl, alt, shift, meta, kind })
}
EOF
"}

actions.command:
cat > src/app.rs <<'EOF'
use crate::exec;
use crate::keymap::{Action, Key, KeyKind};
use crate::result::{CommandResultData, DiffMode, OutputMode};
use crate::textgen::{create_text, summary_counts, TextOptions};
use crate::{append_log, spawn_aftercommand, AppConfig};
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers, MouseButton, MouseEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
    widgets::{Block, BorderType, Borders, Clear, Paragraph, Scrollbar, ScrollbarOrientation, ScrollbarState, Wrap},
    Frame, Terminal,
};
use std::collections::HashMap;
use std::io::{stdout, Write};
use std::sync::{mpsc, Arc, Mutex};
use std::time::Duration;
use unicode_width::UnicodeWidthChar;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Focus {
    History,
    Watch,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Popup {
    None,
    Help,
    Exit,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum FilterType {
    None,
    Keyword,
    Regex,
}

struct FilterState {
    typ: FilterType,
    text: String,
    editing: bool,
    input: String,
    // Line index (into generated watch text) of the currently focussed match.
    focus_line: Option<usize>,
}
impl FilterState {
    fn new() -> Self {
        Self { typ: FilterType::None, text: String::new(), editing: false, input: String::new(), focus_line: None }
    }
    fn active(&self) -> bool {
        self.typ != FilterType::None && !self.text.is_empty()
    }
    fn reset(&mut self) {
        self.typ = FilterType::None;
        self.text.clear();
        self.input.clear();
        self.editing = false;
        self.focus_line = None;
    }
}

pub struct App {
    cfg: AppConfig,
    history: Vec<CommandResultData>,
    latest: Option<CommandResultData>,
    // None = virtual "latest", Some(pos) = position in displayed entries (0 = newest displayed)
    selection: Option<usize>,
    focus: Focus,
    watch_scroll_y: usize,
    watch_scroll_x: usize,
    history_scroll_y: usize,
    help_scroll: usize,
    popup: Popup,
    show_title: bool,
    show_history: bool,
    show_summary: bool,
    wrap: bool,
    filter: FilterState,
    summaries: HashMap<usize, crate::textgen::Summary>,
    should_quit: bool,
    pending_beep: bool,
    last_watch_area: Rect,
    last_history_area: Rect,
    last_frame_size: Rect,
    last_help_inner_h: u16,
    header_width: u16,
    header_dirty: bool,
    interval_shared: Arc<Mutex<f64>>,
    paused_shared: Arc<Mutex<bool>>,
}

pub fn run(config: AppConfig, loaded: Vec<CommandResultData>, last: Option<CommandResultData>) -> i32 {
    let (tx, rx) = mpsc::channel::<CommandResultData>();
    let interval_shared = Arc::new(Mutex::new(config.interval));
    let paused_shared = Arc::new(Mutex::new(false));
    let exec_cfg = Arc::new(exec::ExecConfig {
        command: config.command.clone(),
        shell: config.shell.clone(),
        is_exec: config.is_exec,
    });
    let _tx_keepalive = tx.clone();
    exec::spawn_exec_thread(
        exec_cfg,
        interval_shared.clone(),
        paused_shared.clone(),
        config.precise,
        tx,
    );

    if enable_raw_mode().is_err() {
        return 0;
    }
    let mut out = stdout();
    let _ = execute!(out, EnterAlternateScreen);
    if config.mouse {
        let _ = execute!(out, crossterm::event::EnableMouseCapture);
    } else {
        let _ = execute!(out, crossterm::event::DisableMouseCapture);
    }
    let backend = CrosstermBackend::new(out);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            return 0;
        }
    };
    let _ = terminal.clear();
    let _ = terminal.hide_cursor();

    let mut app = App {
        show_title: !config.no_title,
        show_history: true,
        cfg: config,
        history: loaded,
        latest: last,
        selection: None,
        focus: Focus::History,
        watch_scroll_y: 0,
        watch_scroll_x: 0,
        history_scroll_y: 0,
        help_scroll: 0,
        popup: Popup::None,
        show_summary: false,
        wrap: true,
        filter: FilterState::new(),
        summaries: HashMap::new(),
        should_quit: false,
        pending_beep: false,
        last_watch_area: Rect::default(),
        last_history_area: Rect::default(),
        last_frame_size: Rect::default(),
        last_help_inner_h: 0,
        header_width: 0,
        header_dirty: false,
        interval_shared,
        paused_shared,
    };

    let mut dirty = true;
    loop {
        // Drain exec results.
        while let Ok(result) = rx.try_recv() {
            app.on_result(result);
            dirty = true;
        }
        if dirty {
            if terminal.draw(|f| app.draw(f)).is_err() {
                break;
            }
            if app.pending_beep {
                let _ = terminal.backend_mut().write_all(b"\x07");
                let _ = terminal.backend_mut().flush();
                app.pending_beep = false;
            }
            dirty = false;
        }
        if app.should_quit {
            break;
        }
        match event::poll(Duration::from_millis(20)) {
            Ok(true) => {
                if let Ok(ev) = event::read() {
                    app.handle_event(ev);
                    dirty = true;
                    if app.should_quit {
                        break;
                    }
                }
            }
            Ok(false) => {}
            Err(_) => break,
        }
    }

    let _ = terminal.show_cursor();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = execute!(terminal.backend_mut(), crossterm::event::DisableMouseCapture);
    let _ = disable_raw_mode();
    0
}

impl App {
    fn on_result(&mut self, result: CommandResultData) {
        let is_changed = match self.history.last() {
            Some(last) => !result.eq_without_timestamp(last),
            None => !result.eq_without_timestamp(&CommandResultData::default()),
        };
        if !is_changed {
            return;
        }
        let before = self
            .history
            .last()
            .cloned()
            .unwrap_or_default();
        self.latest = Some(result.clone());
        self.history.push(result.clone());
        // Prune to limit.
        if self.cfg.limit > 0 {
            while self.history.len() > self.cfg.limit as usize {
                self.history.remove(0);
                self.summaries.clear();
                if let Some(pos) = self.selection {
                    // selection is positional from the newest; pruning the
                    // oldest shifts nothing unless it removed the selected one.
                    let disp_len = self.displayed_indices().len();
                    if pos >= disp_len {
                        self.selection = None;
                    }
                }
            }
        }
        if let Some(ref lf) = self.cfg.logfile {
            append_log(lf, &result);
        }
        if let Some(ref ac) = self.cfg.after_command {
            spawn_aftercommand(ac, &before, &result);
        }
        if self.cfg.beep {
            self.pending_beep = true;
        }
        self.header_dirty = true;
    }

    fn selected_result(&self) -> (CommandResultData, CommandResultData) {
        // Returns (after, before) for text generation.
        let target = match self.selection {
            None => self
                .latest
                .clone()
                .or_else(|| self.history.last().cloned())
                .unwrap_or_default(),
            Some(pos) => {
                let idxs = self.displayed_indices();
                if let Some(&hi) = idxs.get(pos) {
                    self.history[hi].clone()
                } else {
                    self.latest.clone().unwrap_or_default()
                }
            }
        };
        // Find the position of target in history (by identity of the entry
        // it corresponds to) to locate its predecessor.
        let before = match self.selection {
            None => {
                // Latest corresponds to the last history entry.
                if self.history.len() >= 2 {
                    self.history[self.history.len() - 2].clone()
                } else {
                    target.clone()
                }
            }
            Some(pos) => {
                let idxs = self.displayed_indices();
                if let Some(&hi) = idxs.get(pos) {
                    if hi > 0 {
                        self.history[hi - 1].clone()
                    } else {
                        target.clone()
                    }
                } else {
                    target.clone()
                }
            }
        };
        (target, before)
    }

    fn displayed_indices(&self) -> Vec<usize> {
        let mut out = Vec::new();
        for idx in (0..self.history.len()).rev() {
            let entry = &self.history[idx];
            // Output-mode filter.
            match self.cfg.output_mode {
                OutputMode::Output => {}
                OutputMode::Stdout => {
                    let prev = if idx > 0 { self.history[idx - 1].stdout.as_str() } else { "" };
                    if entry.stdout == prev {
                        continue;
                    }
                }
                OutputMode::Stderr => {
                    let prev = if idx > 0 { self.history[idx - 1].stderr.as_str() } else { "" };
                    if entry.stderr == prev {
                        continue;
                    }
                }
            }
            // Keyword / regex filter.
            if self.filter.active() {
                let text = entry.selected(self.cfg.output_mode);
                let ok = match self.filter.typ {
                    FilterType::Keyword => text.contains(&self.filter.text),
                    FilterType::Regex => match regex::Regex::new(&self.filter.text) {
                        Ok(re) => re.is_match(text),
                        Err(_) => true,
                    },
                    FilterType::None => true,
                };
                if !ok {
                    continue;
                }
            }
            out.push(idx);
        }
        out
    }

    fn summary_for(&mut self, idx: usize) -> crate::textgen::Summary {
        if let Some(s) = self.summaries.get(&idx) {
            return *s;
        }
        let before_text = if idx > 0 {
            self.history[idx - 1].selected(self.cfg.output_mode).to_string()
        } else {
            String::new()
        };
        let after_text = self.history[idx].selected(self.cfg.output_mode).to_string();
        let s = summary_counts(&before_text, &after_text, self.cfg.enable_summary_char);
        self.summaries.insert(idx, s);
        s
    }

    fn watch_text(&self) -> Text<'static> {
        let (after, before) = self.selected_result();
        let opt = TextOptions {
            diff_mode: self.cfg.diff_mode,
            diff_only: self.cfg.diff_output_only,
            line_number: self.cfg.line_number,
            reverse: self.cfg.reverse,
            output_mode: self.cfg.output_mode,
            ansi: self.cfg.color,
        };
        let text = create_text(&after, &before, &opt);
        let text = self.expand_tabs(text);
        let text = if self.cfg.color { text } else { escape_esc(text) };
        let text = self.apply_keyword_highlight(text);
        text
    }

    fn expand_tabs(&self, text: Text<'static>) -> Text<'static> {
        let tab = self.cfg.tab_size as usize;
        let mut lines: Vec<Line<'static>> = Vec::new();
        for line in text.lines {
            let alignment = line.alignment;
            // Flatten to (char, style)
            let mut chars: Vec<(char, Style)> = Vec::new();
            for span in &line.spans {
                for ch in span.content.chars() {
                    chars.push((ch, span.style));
                }
            }
            let mut out: Vec<(char, Style)> = Vec::new();
            let mut col = 0usize;
            for (ch, st) in chars {
                if ch == '\t' {
                    if tab == 0 {
                        continue;
                    }
                    let n = tab - (col % tab);
                    for _ in 0..n {
                        out.push((' ', st));
                        col += 1;
                    }
                } else {
                    col += UnicodeWidthChar::width(ch).unwrap_or(0);
                    out.push((ch, st));
                }
            }
            lines.push(chars_to_line(out, alignment));
        }
        Text::from(lines)
    }

    fn apply_keyword_highlight(&self, text: Text<'static>) -> Text<'static> {
        if !self.filter.active() {
            return text;
        }
        let re: Option<regex::Regex> = match self.filter.typ {
            FilterType::Regex => regex::Regex::new(&self.filter.text).ok(),
            _ => None,
        };
        if self.filter.typ == FilterType::Regex && re.is_none() {
            return text;
        }
        let hl = Style::default().fg(Color::Black).bg(Color::Yellow);
        let mut lines: Vec<Line<'static>> = Vec::new();
        for line in text.lines {
            let alignment = line.alignment;
            let mut chars: Vec<(char, Style)> = Vec::new();
            for span in &line.spans {
                for ch in span.content.chars() {
                    chars.push((ch, span.style));
                }
            }
            let s: String = chars.iter().map(|c| c.0).collect();
            // Compute highlighted char ranges (byte ranges converted).
            let mut hl_flags = vec![false; chars.len()];
            let matches: Vec<(usize, usize)> = match self.filter.typ {
                FilterType::Keyword => {
                    let mut v = Vec::new();
                    if !self.filter.text.is_empty() {
                        let mut start = 0usize;
                        while let Some(pos) = s[start..].find(&self.filter.text) {
                            let a = start + pos;
                            v.push((a, a + self.filter.text.len()));
                            start = a + self.filter.text.len();
                            if start >= s.len() { break; }
                        }
                    }
                    v
                }
                FilterType::Regex => re
                    .as_ref()
                    .map(|r| r.find_iter(&s).map(|m| (m.start(), m.end())).collect())
                    .unwrap_or_default(),
                FilterType::None => Vec::new(),
            };
            // Map byte offsets to char indices.
            let mut byte_to_char: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();
            for (ci, (bi, _)) in s.char_indices().enumerate() {
                byte_to_char.insert(bi, ci);
            }
            byte_to_char.insert(s.len(), chars.len());
            for (a, b) in matches {
                if let (Some(&ca), Some(&cb)) = (byte_to_char.get(&a), byte_to_char.get(&b)) {
                    for f in hl_flags.iter_mut().take(cb).skip(ca) {
                        *f = true;
                    }
                }
            }
            let out: Vec<(char, Style)> = chars
                .into_iter()
                .enumerate()
                .map(|(i, (ch, st))| (ch, if hl_flags[i] { hl } else { st }))
                .collect();
            lines.push(chars_to_line(out, alignment));
        }
        Text::from(lines)
    }

    // ---------------- drawing ----------------

    fn draw(&mut self, frame: &mut Frame) {
        let size = frame.area();
        self.last_frame_size = size;
        if self.header_dirty {
            self.header_width = size.width;
            self.header_dirty = false;
        }
        let show_header = self.show_title;
        let header_h: u16 = if show_header { 2 } else { 0 };
        let border_top_h: u16 = if show_header && self.cfg.border { 1 } else { 0 };
        let body_y = header_h + border_top_h;
        let body_h = size.height.saturating_sub(body_y);
        let history_visible = self.show_history && self.show_title || (self.show_history && !self.show_title && self.history_toggled_after_title());
        // NOTE: `t` hides both header and history; BSpace toggles history independently.
        let history_visible = self.effective_history_visible();
        let _ = history_visible;

        if show_header {
            let header_area = Rect::new(0, 0, size.width, 2.min(size.height));
            frame.render_widget(Paragraph::new(self.header_text()), header_area);
            if self.cfg.border && size.height > 2 {
                let y = 2;
                let watch_w = self.watch_width(size.width);
                let mut line = String::new();
                for x in 0..size.width {
                    if self.effective_history_visible() && watch_w > 0 && x == watch_w - 1 {
                        line.push('┬');
                    } else {
                        line.push('─');
                    }
                }
                frame.render_widget(
                    Paragraph::new(Line::from(Span::styled(line, Style::default().fg(Color::Gray)))),
                    Rect::new(0, y, size.width, 1),
                );
            }
        }

        let watch_w = self.watch_width(size.width);
        let hist_w = size.width.saturating_sub(watch_w);
        let watch_area_full = Rect::new(0, body_y, watch_w, body_h);
        let hist_area = Rect::new(watch_w, body_y, hist_w, body_h);
        self.last_history_area = hist_area;

        // Watch pane: with border, the right column is the divider/scrollbar.
        let watch_inner_w = if self.cfg.border {
            watch_w.saturating_sub(1)
        } else {
            watch_w
        };
        let watch_area = Rect::new(0, body_y, watch_inner_w, body_h);
        self.last_watch_area = Rect::new(0, body_y.saturating_sub(border_top_h), watch_w, body_h + border_top_h);

        if watch_area.width > 0 && watch_area.height > 0 {
            let text = self.watch_text();
            // Clamp scroll.
            let max_y = self.max_watch_scroll_y(&text, watch_area.width, watch_area.height);
            if self.watch_scroll_y > max_y {
                self.watch_scroll_y = max_y;
            }
            let max_x = self.max_watch_scroll_x(&text, watch_area.width);
            if self.watch_scroll_x > max_x {
                self.watch_scroll_x = max_x;
            }
            let mut p = Paragraph::new(text.clone())
                .scroll((self.watch_scroll_y as u16, self.watch_scroll_x as u16));
            if self.wrap {
                p = p.wrap(Wrap { trim: false });
            }
            frame.render_widget(p, watch_area);
            if self.cfg.border && watch_w > 0 {
                let divider_x = watch_w - 1;
                if self.cfg.with_scrollbar {
                    let total = self.watch_display_line_count(&text, watch_area.width);
                    let mut state = ScrollbarState::new(total)
                        .viewport_content_length(watch_area.height as usize)
                        .position(self.watch_scroll_y);
                    let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight)
                        .begin_symbol(None)
                        .end_symbol(None)
                        .track_symbol(Some("│"))
                        .thumb_symbol("█");
                    frame.render_stateful_widget(
                        sb,
                        Rect::new(divider_x, body_y, 1, body_h),
                        &mut state,
                    );
                } else {
                    let s: String = std::iter::repeat_n("│\n", body_h as usize).collect();
                    frame.render_widget(
                        Paragraph::new(s.trim_end_matches('\n').to_string()),
                        Rect::new(divider_x, body_y, 1, body_h),
                    );
                }
            }
            let _ = watch_area_full;
        }

        if self.effective_history_visible() && hist_area.width > 0 && hist_area.height > 0 {
            let hist_text = self.history_text();
            // Adjust scroll to keep the selected line visible.
            let sel_line = self.selected_history_line();
            let h = hist_area.height as usize;
            if h > 0 {
                if sel_line < self.history_scroll_y {
                    self.history_scroll_y = sel_line;
                } else if sel_line >= self.history_scroll_y + h {
                    self.history_scroll_y = sel_line + 1 - h;
                }
            }
            let p = Paragraph::new(hist_text).scroll((self.history_scroll_y as u16, 0));
            frame.render_widget(p, hist_area);
        }

        match self.popup {
            Popup::Help => self.draw_help(frame),
            Popup::Exit => self.draw_exit(frame),
            Popup::None => {}
        }
    }

    fn history_toggled_after_title(&self) -> bool {
        false
    }

    fn effective_history_visible(&self) -> bool {
        self.show_history && self.show_title_visible_for_history()
    }

    fn show_title_visible_for_history(&self) -> bool {
        // `t` toggles a single flag that controls both header and history.
        // We model that with show_title itself for the common case, but
        // BSpace can re-show history while the header stays hidden: that is
        // tracked by setting show_history=true while show_title=false and
        // remembering it in history_forced.
        self.show_title || self.history_forced()
    }

    fn history_forced(&self) -> bool {
        self.history_forced_flag
    }

    fn watch_width(&self, total: u16) -> u16 {
        if self.effective_history_visible() {
            total.saturating_sub(25)
        } else {
            total
        }
    }

    fn header_text(&self) -> Text<'static> {
        let latest = self.latest.clone().unwrap_or_default();
        let interval_text = if *self.paused_shared.lock().unwrap() {
            format!("{:>9}", "Paused")
        } else {
            format!("{:>9.3}", self.cfg.interval)
        };
        let w = self.header_width as usize;
        let cmd_width = if self.cfg.no_help_banner {
            w.saturating_sub(41)
        } else {
            w.saturating_sub(66)
        };
        let cmd_field = format!("{:<width$}", latest.command, width = cmd_width);
        let cmd_color = if latest.status { Color::Green } else { Color::Red };
        let mut line1: Vec<Span<'static>> = vec![
            Span::raw("Every "),
            Span::styled(interval_text, Style::default().fg(Color::Cyan)),
            Span::raw(":"),
            Span::styled(cmd_field, Style::default().fg(cmd_color)),
            Span::raw(" "),
        ];
        if !self.cfg.no_help_banner {
            line1.push(Span::styled(
                "Display help with h key!".to_string(),
                Style::default().add_modifier(Modifier::REVERSED),
            ));
            line1.push(Span::raw(" "));
        }
        line1.push(Span::styled(latest.timestamp.clone(), Style::default().fg(Color::Cyan)));

        // Second line: filter field + boxes.
        let boxes = self.header_boxes();
        let boxes_len = 58usize;
        let field_w = (self.header_width as usize).saturating_sub(boxes_len + 1);
        let mut line2: Vec<Span<'static>> = Vec::new();
        if self.filter.typ != FilterType::None || self.filter.editing {
            let mark = if self.filter.editing && !self.filter.text.is_empty() {
                ' '
            } else {
                match self.filter.typ {
                    FilterType::Keyword => '/',
                    FilterType::Regex => '*',
                    FilterType::None => ' ',
                }
            };
            let shown = if self.filter.editing { &self.filter.input } else { &self.filter.text };
            line2.push(Span::styled(mark.to_string(), Style::default().fg(Color::Gray)));
            let text_w = field_w.saturating_sub(1);
            let padded = format!("{:<width$}", shown, width = text_w);
            line2.push(Span::styled(
                padded,
                Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
            ));
        } else if field_w > 0 {
            line2.push(Span::styled(" ".repeat(field_w), Style::default().fg(Color::Gray)));
        }
        line2.extend(boxes);
        Text::from(vec![Line::from(line1), Line::from(line2)])
    }

    fn header_boxes(&self) -> Vec<Span<'static>> {
        let on = Style::default().fg(Color::Green).add_modifier(Modifier::BOLD | Modifier::REVERSED);
        let off = Style::default();
        let mut v: Vec<Span<'static>> = Vec::new();
        let mut bx = |label: &str, style: Style, v: &mut Vec<Span<'static>>| {
            v.push(Span::raw("["));
            v.push(Span::styled(label.to_string(), style));
            v.push(Span::raw("] "));
        };
        bx("Number", if self.cfg.line_number { on } else { off }, &mut v);
        bx("Color", if self.cfg.color { on } else { off }, &mut v);
        bx("Reverse", if self.cfg.reverse { on } else { off }, &mut v);
        bx(
            self.cfg.output_mode.label(),
            Style::default().fg(Color::Yellow).add_modifier(Modifier::REVERSED),
            &mut v,
        );
        let focus_label = match self.focus {
            Focus::History => "History".to_string(),
            Focus::Watch => format!("{:<7}", "Watch"),
        };
        bx(
            &focus_label,
            Style::default().fg(Color::Cyan).add_modifier(Modifier::REVERSED),
            &mut v,
        );
        let diff_label = {
            let base = self.cfg.diff_mode.label();
            let s = if self.cfg.diff_output_only
                && matches!(self.cfg.diff_mode, DiffMode::Line | DiffMode::Word)
            {
                format!("{}(Only)", base)
            } else {
                base.to_string()
            };
            format!("{:<10}", s)
        };
        v.push(Span::raw("["));
        v.push(Span::styled(
            diff_label,
            Style::default().fg(Color::Magenta).add_modifier(Modifier::REVERSED),
        ));
        v.push(Span::raw("]"));
        v
    }

    fn history_lines(&mut self) -> Vec<Line<'static>> {
        let mut lines: Vec<Line<'static>> = Vec::new();
        let sel = self.selection;
        let focus_bg = if self.focus == Focus::History { Color::Blue } else { Color::DarkGray };
        // Virtual latest line.
        if sel.is_none() {
            lines.push(Line::from(Span::styled(
                ">>latest".to_string(),
                Style::default().fg(Color::Gray).bg(focus_bg).add_modifier(Modifier::BOLD),
            )));
        } else {
            lines.push(Line::from(Span::raw("  latest".to_string())));
        }
        let idxs = self.displayed_indices();
        // Summaries must be computed before borrowing history immutably below.
        let mut summaries: std::collections::HashMap<usize, crate::textgen::Summary> = std::collections::HashMap::new();
        if self.show_summary {
            for &hi in &idxs {
                summaries.insert(hi, self.summary_for(hi));
            }
        }
        for (pos, &hi) in idxs.iter().enumerate() {
            let entry = &self.history[hi];
            if sel == Some(pos) {
                lines.push(Line::from(Span::styled(
                    format!(">>{}", entry.timestamp),
                    Style::default().fg(Color::Gray).bg(focus_bg).add_modifier(Modifier::BOLD),
                )));
            } else {
                let color = if entry.status { Color::Green } else { Color::Red };
                lines.push(Line::from(vec![
                    Span::raw("  ".to_string()),
                    Span::styled(entry.timestamp.clone(), Style::default().fg(color)),
                ]));
            }
            if self.show_summary {
                if let Some(s) = summaries.get(&hi) {
                    lines.push(Line::from(vec![
                        Span::raw(" Line: ".to_string()),
                        Span::styled(format!("+{:>7}", s.line_plus), Style::default().fg(Color::Green)),
                        Span::raw(" ".to_string()),
                        Span::styled(format!("-{:>7}", s.line_minus), Style::default().fg(Color::Red)),
                    ]));
                    if self.cfg.enable_summary_char {
                        lines.push(Line::from(vec![
                            Span::raw(" Char: ".to_string()),
                            Span::styled(format!("+{:>7}", s.char_plus), Style::default().fg(Color::Green)),
                            Span::raw(" ".to_string()),
                            Span::styled(format!("-{:>7}", s.char_minus), Style::default().fg(Color::Red)),
                        ]));
                    }
                }
            }
        }
        lines
    }

    fn history_text(&mut self) -> Text<'static> {
        Text::from(self.history_lines())
    }

    fn selected_history_line(&self) -> usize {
        match self.selection {
            None => 0,
            Some(pos) => {
                let mut line = 1usize;
                let per = if self.show_summary {
                    1 + if self.cfg.enable_summary_char { 2 } else { 1 }
                } else {
                    1
                };
                line += pos * per;
                line
            }
        }
    }

    fn watch_display_line_count(&self, text: &Text<'_>, width: u16) -> usize {
        if width == 0 {
            return text.lines.len();
        }
        if !self.wrap {
            return text.lines.len();
        }
        let mut count = 0usize;
        for line in &text.lines {
            let w: usize = line
                .spans
                .iter()
                .map(|s| s.content.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum::<usize>())
                .sum();
            if w == 0 {
                count += 1;
            } else {
                count += (w + width as usize - 1) / width as usize;
            }
        }
        count
    }

    fn max_watch_scroll_y(&self, text: &Text<'_>, width: u16, height: u16) -> usize {
        let total = self.watch_display_line_count(text, width);
        total.saturating_sub(height as usize + 1)
    }
    fn max_watch_scroll_x(&self, text: &Text<'_>, width: u16) -> usize {
        if self.wrap {
            return 0;
        }
        let maxw = text
            .lines
            .iter()
            .map(|l| {
                l.spans
                    .iter()
                    .map(|s| s.content.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum::<usize>())
                    .sum::<usize>()
            })
            .max()
            .unwrap_or(0);
        maxw.saturating_sub(width as usize)
    }

    fn popup_rect(&self, percent_x: u16, percent_y: u16, area: Rect) -> Rect {
        let v = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Percentage((100 - percent_y) / 2),
                Constraint::Percentage(percent_y),
                Constraint::Percentage((100 - percent_y) / 2),
            ])
            .split(area);
        let h = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Percentage((100 - percent_x) / 2),
                Constraint::Percentage(percent_x),
                Constraint::Percentage((100 - percent_x) / 2),
            ])
            .split(v[1]);
        h[1]
    }

    fn draw_help(&mut self, frame: &mut Frame) {
        let area = self.popup_rect(80, 70, frame.area());
        let mut lines: Vec<Line<'static>> = Vec::new();
        let base = Style::default().fg(Color::LightGreen);
        for &action in Action::all_in_order() {
            for (k, a) in self.cfg.keymap.iter() {
                if *a == action {
                    lines.push(Line::from(vec![
                        Span::styled(" - [".to_string(), base),
                        Span::styled(format!("{}", k), Style::default().fg(Color::Yellow)),
                        Span::styled("] key :".to_string(), base),
                    ]));
                    lines.push(Line::from(vec![
                        Span::styled("         ".to_string(), base),
                        Span::styled(
                            action.description().to_string(),
                            Style::default().fg(Color::White),
                        ),
                    ]));
                }
            }
        }
        lines.push(Line::from(""));
        lines.push(Line::from(""));
        let inner_h = area.height.saturating_sub(2);
        self.last_help_inner_h = inner_h;
        let max_scroll = (lines.len()).saturating_sub(inner_h as usize);
        if self.help_scroll > max_scroll {
            self.help_scroll = max_scroll;
        }
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Plain)
            .border_style(Style::default().fg(Color::Gray))
            .title(" [help] ");
        let p = Paragraph::new(Text::from(lines))
            .style(base)
            .block(block)
            .scroll((self.help_scroll as u16, 0));
        frame.render_widget(Clear, area);
        frame.render_widget(p, area);
    }

    fn draw_exit(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let w = 32u16.min(area.width);
        let h = 5u16.min(area.height);
        let x = area.x + area.width.saturating_sub(w) / 2;
        let y = area.y + area.height.saturating_sub(h) / 2;
        let rect = Rect::new(x, y, w, h);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Double)
            .border_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))
            .title(" [exit] ");
        let text = Text::from(vec![
            Line::from(" Exit hwatch?"),
            Line::from("   Press 'Y' or 'Q'  : Quit."),
            Line::from("   Press 'N' or 'Esc': Stay."),
        ]);
        let p = Paragraph::new(text).block(block);
        frame.render_widget(Clear, rect);
        frame.render_widget(p, rect);
    }

    // ---------------- events ----------------

    fn handle_event(&mut self, ev: Event) {
        match ev {
            Event::Key(key) => self.handle_key(key),
            Event::Mouse(me) => self.handle_mouse(me.kind, me.column, me.row),
            Event::Resize(_, _) => {
                self.header_dirty = true;
            }
            _ => {}
        }
    }

    fn handle_mouse(&mut self, kind: MouseEventKind, col: u16, row: u16) {
        let key = match kind {
            MouseEventKind::ScrollUp => Key::new(KeyKind::MouseScrollUp),
            MouseEventKind::ScrollDown => Key::new(KeyKind::MouseScrollDown),
            MouseEventKind::ScrollLeft => Key::new(KeyKind::MouseScrollLeft),
            MouseEventKind::ScrollRight => Key::new(KeyKind::MouseScrollRight),
            MouseEventKind::Down(MouseButton::Left) => Key::new(KeyKind::MouseButtonDownLeft),
            MouseEventKind::Down(MouseButton::Right) => Key::new(KeyKind::MouseButtonDownRight),
            MouseEventKind::Up(MouseButton::Left) => Key::new(KeyKind::MouseButtonUpLeft),
            MouseEventKind::Up(MouseButton::Right) => Key::new(KeyKind::MouseButtonUpRight),
            _ => return,
        };
        if let Some(&action) = self.cfg.keymap.get(&key) {
            self.do_action(action, Some((col, row)));
        }
    }

    fn handle_key(&mut self, key: KeyEvent) {
        if key.kind == event::KeyEventKind::Release {
            return;
        }
        // Filter editing takes most keys.
        if self.filter.editing {
            match key.code {
                KeyCode::Enter => {
                    self.filter.text = self.filter.input.clone();
                    self.filter.editing = false;
                    self.selection = None;
                    self.focus_first_keyword();
                    self.header_dirty = true;
                    return;
                }
                KeyCode::Backspace => {
                    self.filter.input.pop();
                    self.header_dirty = true;
                    return;
                }
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    // Only the Cancel action bound to Ctrl-C matters here.
                    if let Some(k) = key_from_event(&key) {
                        if self.cfg.keymap.get(&k) == Some(&Action::Cancel) {
                            self.filter.editing = false;
                            self.filter.input = self.filter.text.clone();
                            self.header_dirty = true;
                            return;
                        }
                    }
                }
                KeyCode::Char(c) => {
                    if !c.is_control() {
                        self.filter.input.push(c);
                        self.header_dirty = true;
                    }
                    return;
                }
                _ => return,
            }
        }
        // Raw exit-confirmation keys.
        if self.popup == Popup::Exit {
            if let KeyCode::Char(c) = key.code {
                if !key.modifiers.contains(KeyModifiers::CONTROL) {
                    match c {
                        'y' | 'q' => {
                            self.should_quit = true;
                            return;
                        }
                        'n' => {
                            self.popup = Popup::None;
                            return;
                        }
                        _ => {}
                    }
                }
            }
        }
        if let Some(k) = key_from_event(&key) {
            if let Some(&action) = self.cfg.keymap.get(&k) {
                self.do_action(action, None);
            }
        }
    }

    fn focus_first_keyword(&mut self) {
        self.filter.focus_line = None;
        self.move_keyword(true, true);
    }

    fn keyword_match_lines(&self) -> Vec<usize> {
        if !self.filter.active() {
            return Vec::new();
        }
        let text = self.watch_text();
        let re: Option<regex::Regex> = match self.filter.typ {
            FilterType::Regex => regex::Regex::new(&self.filter.text).ok(),
            _ => None,
        };
        let mut out = Vec::new();
        for (i, line) in text.lines.iter().enumerate() {
            let s: String = line.spans.iter().map(|s| s.content.as_ref()).collect();
            let hit = match self.filter.typ {
                FilterType::Keyword => s.contains(&self.filter.text),
                FilterType::Regex => re.as_ref().map(|r| r.is_match(&s)).unwrap_or(false),
                FilterType::None => false,
            };
            if hit {
                out.push(i);
            }
        }
        out
    }

    fn move_keyword(&mut self, forward: bool, first: bool) {
        let matches = self.keyword_match_lines();
        if matches.is_empty() {
            self.filter.focus_line = None;
            return;
        }
        let next = if first {
            if forward { matches[0] } else { matches[matches.len() - 1] }
        } else {
            match self.filter.focus_line {
                None => {
                    if forward { matches[0] } else { matches[matches.len() - 1] }
                }
                Some(cur) => {
                    if forward {
                        matches.iter().find(|&&m| m > cur).copied().unwrap_or(matches[0])
                    } else {
                        matches.iter().rev().find(|&&m| m < cur).copied().unwrap_or(matches[matches.len() - 1])
                    }
                }
            }
        };
        self.filter.focus_line = Some(next);
        // Reveal it.
        let h = self.last_watch_area.height as usize;
        if h > 0 {
            if next < self.watch_scroll_y {
                self.watch_scroll_y = next;
            } else if next >= self.watch_scroll_y + h {
                self.watch_scroll_y = next + 1 - h;
            }
        }
    }

    fn do_action(&mut self, action: Action, mouse: Option<(u16, u16)>) {
        use Action as A;
        // Help popup consumes scroll keys for itself.
        if self.popup == Popup::Help {
            match action {
                A::Up => {
                    self.help_scroll = self.help_scroll.saturating_sub(1);
                    return;
                }
                A::Down => {
                    self.help_scroll += 1;
                    return;
                }
                A::PageUp => {
                    let amt = self.page_amount(self.last_help_inner_h as usize);
                    self.help_scroll = self.help_scroll.saturating_sub(amt);
                    return;
                }
                A::PageDown => {
                    let amt = self.page_amount(self.last_help_inner_h as usize);
                    self.help_scroll += amt;
                    return;
                }
                A::MoveTop => {
                    self.help_scroll = 0;
                    return;
                }
                A::MoveEnd => {
                    self.help_scroll = usize::MAX / 2;
                    return;
                }
                _ => {}
            }
        }
        match action {
            A::None => {}
            A::Quit => {
                if self.popup == Popup::Exit {
                    self.should_quit = true;
                } else {
                    self.popup = Popup::Exit;
                }
            }
            A::Cancel => {
                if self.popup == Popup::Help {
                    self.popup = Popup::None;
                } else if self.popup == Popup::Exit {
                    self.should_quit = true;
                } else if self.filter.typ != FilterType::None {
                    self.filter.reset();
                    self.selection = None;
                    self.header_dirty = true;
                } else {
                    self.popup = Popup::Exit;
                }
            }
            A::Reset => {
                if self.popup == Popup::Exit {
                    self.popup = Popup::None;
                } else if self.filter.typ != FilterType::None {
                    self.filter.reset();
                    self.selection = None;
                    self.header_dirty = true;
                } else if self.popup != Popup::Help {
                    self.popup = Popup::Exit;
                }
            }
            A::Help => {
                if self.popup == Popup::Help {
                    self.popup = Popup::None;
                } else {
                    self.popup = Popup::Help;
                    self.help_scroll = 0;
                }
            }
            A::Up => self.move_focus(-1, mouse),
            A::Down => self.move_focus(1, mouse),
            A::PageUp => self.move_focus_page(false, mouse),
            A::PageDown => self.move_focus_page(true, mouse),
            A::MoveTop => self.move_focus_home(mouse),
            A::MoveEnd => self.move_focus_end(mouse),
            A::ScrollLeft => {
                self.watch_scroll_x = self.watch_scroll_x.saturating_sub(1);
            }
            A::ScrollRight => {
                self.watch_scroll_x += 1;
            }
            A::ScrollHorizontalHome => {
                self.watch_scroll_x = 0;
            }
            A::ScrollHorizontalEnd => {
                let text = self.watch_text();
                self.watch_scroll_x = self.max_watch_scroll_x(&text, self.last_watch_area.width);
            }
            A::ToggleForcus => {
