            A::ForcusWatchPane => {
                self.focus = Focus::Watch;
                self.header_dirty = true;
            }
            A::ForcusHistoryPane => {
                self.focus = Focus::History;
                self.header_dirty = true;
            }
            A::ToggleColor => {
