    fn page_amount(&self, area_h: usize) -> usize {
        // Page movement is based on the full frame height.
        let h = self.last_frame_size.height as usize;
        if h > 3 { h - 3 } else if area_h > 1 { area_h - 1 } else { 1 }
    }

    fn focus_for_mouse(&self, mouse: Option<(u16, u16)>) -> Focus {
        if let Some((col, _row)) = mouse {
            if self.effective_history_visible() && col >= self.last_history_area.x {
                return Focus::History;
            }
            return Focus::Watch;
        }
        self.focus
    }

    fn move_focus(&mut self, delta: i64, mouse: Option<(u16, u16)>) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => {
                if delta > 0 {
                    self.watch_scroll_y += delta as usize;
                } else {
                    self.watch_scroll_y = self.watch_scroll_y.saturating_sub((-delta) as usize);
                }
            }
            Focus::History => {
                self.move_selection(delta);
            }
        }
    }
    fn move_focus_page(&mut self, down: bool, mouse: Option<(u16, u16)>) {
        let amt = self.page_amount(0) as i64;
        self.move_focus(if down { amt } else { -amt }, mouse);
    }
    fn move_focus_home(&mut self, mouse: Option<(u16, u16)>) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => self.watch_scroll_y = 0,
            Focus::History => {
                self.selection = None;
                self.watch_scroll_y = 0;
                self.watch_scroll_x = 0;
            }
        }
    }
    fn move_focus_end(&mut self, mouse: Option<(u16, u16)>) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => {
                self.watch_scroll_y = usize::MAX / 2;
            }
            Focus::History => {
                let n = self.displayed_indices().len();
                if n > 0 {
                    self.set_selection_pos(n - 1);
                }
            }
        }
    }

    fn set_selection_pos(&mut self, pos: usize) {
        self.selection = Some(pos);
        self.watch_scroll_y = 0;
        self.watch_scroll_x = 0;
    }

    fn move_selection(&mut self, delta: i64) {
        let n = self.displayed_indices().len();
        // Positions: -1 = latest (None), 0..n-1 = displayed entries.
        let cur: i64 = match self.selection {
            None => -1,
            Some(p) => p as i64,
        };
        let mut next = cur + delta;
        if next < -1 {
            next = -1;
        }
        if next > n as i64 - 1 {
            next = n as i64 - 1;
        }
        if next == cur {
            return;
        }
        if next < 0 {
            self.selection = None;
            self.watch_scroll_y = 0;
            self.watch_scroll_x = 0;
        } else {
            self.set_selection_pos(next as usize);
        }
    }

    fn mouse_scroll(&mut self, mouse: Option<(u16, u16)>, dir: i64) {
        match self.focus_for_mouse(mouse) {
            Focus::Watch => {
                if dir > 0 {
                    self.watch_scroll_y += 2;
                } else {
                    self.watch_scroll_y = self.watch_scroll_y.saturating_sub(2);
                }
            }
            Focus::History => {
                self.move_selection(dir);
            }
        }
    }

    fn mouse_click(&mut self, mouse: Option<(u16, u16)>) {
        if let Some((col, row)) = mouse {
            if self.effective_history_visible()
                && col >= self.last_history_area.x
                && col < self.last_history_area.x + self.last_history_area.width
                && row >= self.last_history_area.y
                && row < self.last_history_area.y + self.last_history_area.height
            {
                let line = self.history_scroll_y + (row - self.last_history_area.y) as usize;
                if line == 0 {
                    self.selection = None;
                    self.watch_scroll_y = 0;
                    self.watch_scroll_x = 0;
                    return;
                }
                let per = if self.show_summary {
                    1 + if self.cfg.enable_summary_char { 2 } else { 1 }
                } else {
                    1
                };
                let pos = (line - 1) / per;
                if pos < self.displayed_indices().len() {
                    self.set_selection_pos(pos);
                }
            }
        }
    }
}

fn chars_to_line(chars: Vec<(char, Style)>, alignment: Option<ratatui::layout::Alignment>) -> Line<'static> {
    let mut spans: Vec<Span<'static>> = Vec::new();
    for (ch, st) in chars {
        if let Some(last) = spans.last_mut() {
            let last: &mut Span<'static> = last;
            if last.style == st {
                last.content.to_mut().push(ch);
                continue;
            }
        }
        spans.push(Span::styled(ch.to_string(), st));
    }
    if spans.is_empty() {
        spans.push(Span::raw(""));
    }
    let mut line = Line::from(spans);
    line.alignment = alignment;
    line
}

fn escape_esc(text: Text<'static>) -> Text<'static> {
    let mut lines = Vec::new();
    for line in text.lines {
        let alignment = line.alignment;
        let mut spans = Vec::new();
        for span in line.spans {
            if span.content.contains('\x1b') {
                spans.push(Span::styled(
                    span.content.replace('\x1b', "\\x1b"),
                    span.style,
                ));
            } else {
                spans.push(span);
            }
        }
        let mut l = Line::from(spans);
        l.alignment = alignment;
        lines.push(l);
    }
    Text::from(lines)
}

fn key_from_event(ev: &KeyEvent) -> Option<Key> {
    let mods = ev.modifiers;
    let ctrl = mods.contains(KeyModifiers::CONTROL);
    let alt = mods.contains(KeyModifiers::ALT);
    let meta = mods.contains(KeyModifiers::META) || mods.contains(KeyModifiers::SUPER);
    let mut shift = mods.contains(KeyModifiers::SHIFT);
    let kind = match ev.code {
        KeyCode::Char(c) => {
            let mut ch = c;
            if c.is_ascii_uppercase() {
                ch = c.to_ascii_lowercase();
                shift = true;
            }
            KeyKind::Char(ch)
        }
        KeyCode::Up => KeyKind::Up,
        KeyCode::Down => KeyKind::Down,
        KeyCode::Left => KeyKind::Left,
        KeyCode::Right => KeyKind::Right,
        KeyCode::Home => KeyKind::Home,
        KeyCode::End => KeyKind::End,
        KeyCode::PageUp => KeyKind::PageUp,
        KeyCode::PageDown => KeyKind::PageDown,
        KeyCode::Backspace => KeyKind::Backspace,
        KeyCode::Delete => KeyKind::Delete,
        KeyCode::Insert => KeyKind::Insert,
        KeyCode::Tab => KeyKind::Tab,
        KeyCode::BackTab => {
            shift = true;
            KeyKind::Tab
        }
        KeyCode::Enter => KeyKind::Enter,
        KeyCode::Esc => KeyKind::Esc,
        KeyCode::F(n) => KeyKind::F(n),
        _ => return None,
    };
    Some(Key { ctrl, alt, shift, meta, kind })
}
