            for f in 0..2usize {
                let cur = dp[idx(i, j, f)];
                if cur == neg {
                    continue;
                }
                // delete old i
                if i < n {
                    let t = &mut dp[idx(i + 1, j, 0)];
                    if cur > *t {
                        *t = cur;
                    }
                }
                // insert new j
                if j < m {
                    let t = &mut dp[idx(i, j + 1, 0)];
                    if cur > *t {
                        *t = cur;
                    }
                }
                // match
                if i < n && j < m && old[i] == new[j] {
                    let add = pack(1, if f == 1 { 1 } else { 0 }, old[i].chars().count() as i64);
                    let t = &mut dp[idx(i + 1, j + 1, 1)];
                    if cur + add > *t {
                        *t = cur + add;
                    }
                }
            }
        }
    }
    // Backtrack.
    let mut ops: Vec<TokOp> = Vec::new();
    let (mut i, mut j) = (n, m);
    let mut f = if dp[idx(n, m, 1)] > dp[idx(n, m, 0)] { 1 } else { 0 };
    while i > 0 || j > 0 {
        if f == 1 {
            // came from a match at (i-1,j-1)
            let cur = dp[idx(i, j, 1)];
            let add1 = pack(1, 1, old[i - 1].chars().count() as i64);
            let add0 = pack(1, 0, old[i - 1].chars().count() as i64);
            let pf = if dp[idx(i - 1, j - 1, 1)] + add1 == cur {
                1
            } else {
                let _ = add0;
                0
            };
            ops.push(TokOp::Both(i - 1, j - 1));
            i -= 1;
            j -= 1;
            f = pf;
        } else {
            let cur = dp[idx(i, j, 0)];
            // Prefer delete in backtracking (=> inserts appear first in
            // forward order), matching the reference span grouping.
            if i > 0
                && (dp[idx(i - 1, j, 0)] == cur || dp[idx(i - 1, j, 1)] == cur)
            {
                let pf = if dp[idx(i - 1, j, 1)] == cur { 1 } else { 0 };
                ops.push(TokOp::Del(i - 1));
                i -= 1;
                f = pf;
            } else if j > 0 {
                let pf = if dp[idx(i, j - 1, 1)] == cur { 1 } else { 0 };
                ops.push(TokOp::Ins(j - 1));
                j -= 1;
                f = pf;
            } else {
                break;
            }
        }
    }
    ops.reverse();
    ops
}
